BOOK.add({
  subject: "math",
  id: "math-15",
  title: "समतलीय आकृतियों का क्षेत्रफल — त्रिभुज, आयत, समांतर चतुर्भुज, समलंब चतुर्भुज",
  notes: "\n<h3>1. मूल अवधारणाएँ — परिमाप और क्षेत्रफल</h3>\n<p><b>परिमाप (Perimeter)</b> = किसी बंद आकृति की सीमा की कुल लंबाई। इकाई — सेमी, मीटर (लंबाई की इकाई)। बाड़ लगाना, तार लगाना, किनारी (बॉर्डर) लगाना, दौड़ना — ये सब परिमाप के प्रश्न हैं।</p>\n<p><b>क्षेत्रफल (Area)</b> = आकृति द्वारा घेरा गया समतल भाग। इकाई — वर्ग सेमी (सेमी²), वर्ग मीटर (मी²)। फर्श, टाइल, रंगाई, कालीन, घास लगाना — ये क्षेत्रफल के प्रश्न हैं।</p>\n<div class=\"tip\">पहचान का नियम: \"चारों ओर / घेरना / बाड़ / तार / चक्कर\" = परिमाप; \"फर्श / ढकना / रंगना / टाइल / घास\" = क्षेत्रफल।</div>\n\n<h3>2. क्षेत्रफल की इकाइयाँ</h3>\n<table>\n<tr><th>इकाई</th><th>मान</th></tr>\n<tr><td>1 वर्ग मीटर</td><td>100 × 100 = 10,000 वर्ग सेमी</td></tr>\n<tr><td>1 वर्ग सेमी</td><td>100 वर्ग मिमी</td></tr>\n<tr><td>1 एयर (are)</td><td>100 वर्ग मीटर (10 मी × 10 मी)</td></tr>\n<tr><td>1 हेक्टेयर</td><td>100 एयर = 10,000 वर्ग मीटर (100 मी × 100 मी)</td></tr>\n<tr><td>1 वर्ग किलोमीटर</td><td>100 हेक्टेयर = 10,00,000 वर्ग मीटर</td></tr>\n</table>\n<p>ध्यान दें: लंबाई में 1 मी = 100 सेमी, पर क्षेत्रफल में 1 मी² = 10,000 सेमी² (वर्ग करना पड़ता है)।</p>\n\n<h3>3. त्रिभुज (Triangle)</h3>\n<table>\n<tr><th>प्रकार</th><th>क्षेत्रफल</th><th>अन्य सूत्र</th></tr>\n<tr><td>कोई भी त्रिभुज</td><td>½ × आधार × ऊँचाई</td><td>परिमाप = a + b + c</td></tr>\n<tr><td>तीनों भुजाएँ ज्ञात (हीरोन सूत्र)</td><td>√(s(s−a)(s−b)(s−c))</td><td>s = (a + b + c)/2 = अर्धपरिमाप</td></tr>\n<tr><td>समकोण त्रिभुज</td><td>½ × लंब × आधार</td><td>कर्ण² = लंब² + आधार²</td></tr>\n<tr><td>समबाहु (भुजा a)</td><td>(√3/4) × a²</td><td>ऊँचाई = (√3/2) × a; परिमाप = 3a</td></tr>\n<tr><td>समद्विबाहु (बराबर भुजा a, आधार b)</td><td>(b/4) × √(4a² − b²)</td><td>ऊँचाई = √(a² − b²/4)</td></tr>\n</table>\n<p><b>प्रमुख पाइथागोरस त्रिक:</b> (3, 4, 5), (5, 12, 13), (8, 15, 17), (7, 24, 25), (20, 21, 29), (9, 40, 41), (12, 35, 37) और इनके गुणज जैसे (6, 8, 10), (9, 12, 15), (15, 20, 25)।</p>\n<p><b>उदाहरण 1:</b> त्रिभुज की भुजाएँ 13, 14, 15 सेमी हैं। क्षेत्रफल?<br>\ns = (13+14+15)/2 = 21; क्षेत्रफल = √(21 × 8 × 7 × 6) = √7056 = <b>84 वर्ग सेमी</b>।</p>\n<p><b>उदाहरण 2:</b> समबाहु त्रिभुज की भुजा 12 सेमी है। क्षेत्रफल = (√3/4) × 144 = <b>36√3 वर्ग सेमी</b>, ऊँचाई = (√3/2) × 12 = 6√3 सेमी।</p>\n<p><b>उदाहरण 3:</b> समद्विबाहु त्रिभुज की बराबर भुजाएँ 13 सेमी व आधार 10 सेमी। ऊँचाई = √(169 − 25) = 12; क्षेत्रफल = ½ × 10 × 12 = <b>60 वर्ग सेमी</b>। (सूत्र से: 10/4 × √(676 − 100) = 2.5 × 24 = 60 ✓)</p>\n<p><b>मध्य-बिंदु नियम:</b> त्रिभुज की भुजाओं के मध्य-बिंदुओं को मिलाने से बना त्रिभुज मूल त्रिभुज के क्षेत्रफल का <b>1/4</b> होता है। माध्यिका (median) त्रिभुज को दो बराबर क्षेत्रफल वाले भागों में बाँटती है।</p>\n\n<h3>4. आयत और वर्ग</h3>\n<table>\n<tr><th>आकृति</th><th>क्षेत्रफल</th><th>परिमाप</th><th>विकर्ण</th></tr>\n<tr><td>आयत (l, b)</td><td>l × b</td><td>2(l + b)</td><td>√(l² + b²)</td></tr>\n<tr><td>वर्ग (भुजा a)</td><td>a² = d²/2</td><td>4a</td><td>a√2</td></tr>\n</table>\n<p><b>उपयोगी सर्वसमिका:</b> (l + b)² = l² + b² + 2lb, अर्थात् (परिमाप/2)² = विकर्ण² + 2 × क्षेत्रफल।</p>\n<p><b>उदाहरण 4:</b> आयत का परिमाप 46 मी और विकर्ण 17 मी है। l + b = 23, l² + b² = 289; 2lb = 529 − 289 = 240 ⇒ क्षेत्रफल = <b>120 मी²</b> (भुजाएँ 15 व 8)।</p>\n<p><b>उदाहरण 5:</b> वर्ग का विकर्ण 10 सेमी ⇒ क्षेत्रफल = 10²/2 = <b>50 वर्ग सेमी</b>।</p>\n<p>नियत परिमाप वाले सभी आयतों में <b>वर्ग का क्षेत्रफल अधिकतम</b> होता है। जैसे परिमाप 60 हो तो अधिकतम क्षेत्रफल = 15 × 15 = 225।</p>\n\n<h3>5. समांतर चतुर्भुज और समचतुर्भुज</h3>\n<table>\n<tr><th>आकृति</th><th>क्षेत्रफल</th><th>परिमाप / अन्य</th></tr>\n<tr><td>समांतर चतुर्भुज</td><td>आधार × संगत ऊँचाई</td><td>2(a + b)</td></tr>\n<tr><td>समचतुर्भुज (rhombus)</td><td>½ × d<sub>1</sub> × d<sub>2</sub> (या आधार × ऊँचाई)</td><td>4a; a² = (d<sub>1</sub>/2)² + (d<sub>2</sub>/2)²</td></tr>\n</table>\n<p>समांतर चतुर्भुज में: क्षेत्रफल = लंबी भुजा × उन पर लंब दूरी = छोटी भुजा × उन पर लंब दूरी। अतः भुजा जितनी छोटी, उस पर ऊँचाई उतनी बड़ी।</p>\n<p>समचतुर्भुज के विकर्ण एक-दूसरे को <b>समकोण पर समद्विभाजित</b> करते हैं, इसलिए भुजा = √((d<sub>1</sub>/2)² + (d<sub>2</sub>/2)²)।</p>\n<p><b>उदाहरण 6:</b> समचतुर्भुज के विकर्ण 16 व 30 सेमी ⇒ भुजा = √(64 + 225) = 17, परिमाप = 68 सेमी, क्षेत्रफल = ½ × 16 × 30 = 240 वर्ग सेमी।</p>\n\n<h3>6. समलंब चतुर्भुज (Trapezium)</h3>\n<p>क्षेत्रफल = ½ × (समांतर भुजाओं का योग) × उनके बीच की दूरी = ½ (a + b) h</p>\n<p><b>उदाहरण 7 (कठिन):</b> समलंब की समांतर भुजाएँ 25 व 11 मी तथा असमांतर भुजाएँ 15 व 13 मी हैं।<br>\nविधि: छोटी भुजा के सिरों से लंब डालने पर 14 (= 25 − 11), 15, 13 भुजाओं वाला त्रिभुज बनता है। उसका क्षेत्रफल (हीरोन) = 84 ⇒ ऊँचाई = 2 × 84/14 = 12 मी। समलंब का क्षेत्रफल = ½ × 36 × 12 = <b>216 मी²</b>।</p>\n\n<h3>7. वृत्त और उसके भाग (π = 22/7)</h3>\n<table>\n<tr><th>आकृति</th><th>परिमाप / लंबाई</th><th>क्षेत्रफल</th></tr>\n<tr><td>वृत्त (त्रिज्या r)</td><td>परिधि = 2πr = πd</td><td>πr²</td></tr>\n<tr><td>अर्धवृत्त</td><td>πr + 2r = (36/7) r</td><td>πr²/2</td></tr>\n<tr><td>चतुर्थांश (quadrant)</td><td>πr/2 + 2r = (25/7) r</td><td>πr²/4</td></tr>\n<tr><td>वलय (बाहरी R, भीतरी r)</td><td>—</td><td>π(R² − r²) = π(R + r)(R − r)</td></tr>\n<tr><td>त्रिज्यखंड (कोण θ)</td><td>चाप l = (θ/360) × 2πr; परिमाप = l + 2r</td><td>(θ/360) × πr² = ½ × l × r</td></tr>\n</table>\n<p><b>सामान्य मान (याद रखें):</b></p>\n<table>\n<tr><th>r</th><th>परिधि</th><th>क्षेत्रफल</th></tr>\n<tr><td>7</td><td>44</td><td>154</td></tr>\n<tr><td>14</td><td>88</td><td>616</td></tr>\n<tr><td>21</td><td>132</td><td>1386</td></tr>\n<tr><td>28</td><td>176</td><td>2464</td></tr>\n<tr><td>35</td><td>220</td><td>3850</td></tr>\n</table>\n<p><b>उदाहरण 8:</b> वृत्त की परिधि 88 सेमी ⇒ r = 88 × 7/44 = 14 ⇒ क्षेत्रफल = 616 वर्ग सेमी।</p>\n<p><b>उदाहरण 9:</b> घड़ी की मिनट की सुई 21 सेमी लंबी है। 10 मिनट में सुई 60° घूमती है (1 मिनट = 6°)। घेरा गया क्षेत्रफल = (60/360) × 1386 = <b>231 वर्ग सेमी</b>।</p>\n\n<h3>8. पहिये के चक्कर (Revolutions)</h3>\n<p>पहिया एक चक्कर में अपनी <b>परिधि</b> जितनी दूरी तय करता है।</p>\n<p>चक्करों की संख्या = कुल दूरी ÷ परिधि; &nbsp; तय दूरी = चक्कर × 2πr</p>\n<p><b>उदाहरण 10:</b> 70 सेमी व्यास का पहिया 66 किमी/घंटा से चल रहा है। प्रति मिनट दूरी = 66000/60 = 1100 मी = 110000 सेमी; परिधि = 220 सेमी ⇒ <b>500 चक्कर प्रति मिनट</b>।</p>\n<p>इकाई सावधानी: त्रिज्या सेमी में और दूरी किमी में हो तो पहले एक इकाई में बदलें।</p>\n\n<h3>9. रास्ते (Paths) — आयताकार मैदान</h3>\n<table>\n<tr><th>स्थिति</th><th>रास्ते का क्षेत्रफल (चौड़ाई w)</th></tr>\n<tr><td>आयत के बाहर चारों ओर</td><td>(l + 2w)(b + 2w) − lb = 2w(l + b) + 4w²</td></tr>\n<tr><td>आयत के अंदर चारों ओर</td><td>lb − (l − 2w)(b − 2w) = 2w(l + b) − 4w²</td></tr>\n<tr><td>बीच में दो क्रॉस-रास्ते (भुजाओं के समांतर)</td><td>w(l + b) − w² = w(l + b − w)</td></tr>\n</table>\n<p>क्रॉस-रास्तों में बीच का w × w वर्ग दो बार गिना जाता है, इसलिए w² घटाते हैं।</p>\n<p><b>उदाहरण 11:</b> 60 मी × 40 मी के बगीचे के बाहर 5 मी चौड़ा रास्ता ⇒ 70 × 50 − 60 × 40 = 3500 − 2400 = <b>1100 मी²</b>। (सूत्र: 2×5×100 + 4×25 = 1100 ✓)</p>\n<p><b>उदाहरण 12:</b> 80 मी × 60 मी के लॉन के बीच 10 मी चौड़े दो क्रॉस-रास्ते ⇒ 10(80 + 60 − 10) = <b>1300 मी²</b>; ₹3 प्रति मी² की दर से बजरी बिछाने का खर्च = ₹3900।</p>\n<p><b>वृत्ताकार रास्ता:</b> r त्रिज्या के बगीचे के बाहर w चौड़ा रास्ता = π[(r + w)² − r²] = πw(2r + w)।</p>\n\n<h3>10. लागत (Cost) के प्रश्न</h3>\n<ul>\n<li>बाड़/तार लगाने की लागत = परिमाप × दर (प्रति मीटर)</li>\n<li>फर्श/घास/बजरी की लागत = क्षेत्रफल × दर (प्रति वर्ग मीटर)</li>\n<li>कमरे की चार दीवारों का क्षेत्रफल = 2h(l + b) — रंगाई की लागत = यह क्षेत्रफल × दर</li>\n<li>टाइलों की संख्या = फर्श का क्षेत्रफल ÷ एक टाइल का क्षेत्रफल (दोनों एक ही इकाई में)</li>\n<li>सबसे बड़ी वर्गाकार टाइल की भुजा = लंबाई व चौड़ाई का <b>म.स.प. (HCF)</b></li>\n<li>कालीन की लंबाई = फर्श का क्षेत्रफल ÷ कालीन की चौड़ाई</li>\n</ul>\n<p><b>उदाहरण 13:</b> 16.8 मी × 12 मी फर्श पर सबसे बड़ी वर्गाकार टाइल: HCF(1680, 1200) सेमी = 240 सेमी। टाइलें = (1680/240) × (1200/240) = 7 × 5 = <b>35</b>।</p>\n\n<h3>11. प्रतिशत परिवर्तन</h3>\n<ul>\n<li>भुजा/त्रिज्या/विकर्ण में x% वृद्धि ⇒ क्षेत्रफल में (2x + x²/100)% वृद्धि</li>\n<li>x% कमी ⇒ क्षेत्रफल में (2x − x²/100)% कमी</li>\n<li>लंबाई x% व चौड़ाई y% बदलें ⇒ क्षेत्रफल में (x + y + xy/100)% परिवर्तन (कमी को ऋणात्मक लें)</li>\n<li>क्षेत्रफल स्थिर रखने हेतु: लंबाई x% बढ़े तो चौड़ाई (100x/(100 + x))% घटानी होगी</li>\n<li>परिमाप/परिधि में परिवर्तन = भुजा/त्रिज्या के समान प्रतिशत</li>\n</ul>\n<p><b>उदाहरण 14:</b> वर्ग की भुजा 20% बढ़ाई ⇒ 20 + 20 + 400/100 = <b>44%</b> वृद्धि।</p>\n\n<h3>12. समान परिमाप वाली आकृतियों की तुलना</h3>\n<p>समान परिमाप होने पर क्षेत्रफल का क्रम: <b>वृत्त &gt; वर्ग &gt; आयत</b> (तथा समबाहु त्रिभुज वर्ग से छोटा)।</p>\n<p>परिमाप 88 हो: वृत्त r = 14, क्षेत्रफल 616; वर्ग भुजा 22, क्षेत्रफल 484। अनुपात 616 : 484 = <b>14 : 11</b>। समान परिमाप पर वृत्त : वर्ग के क्षेत्रफल का अनुपात सदैव 14 : 11 (π = 22/7 पर) होता है।</p>\n<p><b>तार मोड़ने के प्रश्न:</b> तार की लंबाई स्थिर रहती है, अर्थात् नई आकृति का परिमाप = पुरानी आकृति का परिमाप।</p>\n\n<h3>13. अंतर्गत और परिगत आकृतियाँ</h3>\n<ul>\n<li>भुजा a वाले वर्ग में बना सबसे बड़ा वृत्त: r = a/2</li>\n<li>त्रिज्या r वाले वृत्त में बना वर्ग: विकर्ण = 2r, क्षेत्रफल = 2r²</li>\n<li>l × b आयत में सबसे बड़ा वृत्त: व्यास = छोटी भुजा b</li>\n<li>14 सेमी भुजा वाले वर्ग में से अंतर्गत वृत्त निकालने पर बचा भाग = 196 − 154 = 42 वर्ग सेमी</li>\n</ul>\n<div class=\"tip\">परीक्षा में π का मान सामान्यतः 22/7 लेते हैं, इसलिए त्रिज्या/व्यास प्रायः 7 के गुणज होते हैं। यदि उत्तर-विकल्प 7 के गुणजों से बने हैं तो सही विकल्प पहचानना आसान है।</div>\n  ",
  extra: "\n<h3>शॉर्टकट व गहन ट्रिक्स</h3>\n<ul>\n<li><b>हीरोन से पहले जाँचें:</b> क्या भुजाएँ पाइथागोरस त्रिक हैं? (जैसे 9, 12, 15) — तब क्षेत्रफल = ½ × दो छोटी भुजाएँ। 13-14-15 त्रिभुज का क्षेत्रफल 84 और 9-10-17 का 36 — ये बार-बार आते हैं।</li>\n<li><b>13-14-15 की रचना:</b> यह (5, 12, 13) और (9, 12, 15) दो समकोण त्रिभुजों को 12 ऊँचाई पर जोड़कर बनता है; आधार 14 = 5 + 9। इसीलिए ऊँचाई 12 और क्षेत्रफल ½ × 14 × 12 = 84।</li>\n<li><b>समबाहु त्रिभुज:</b> ऊँचाई h हो तो क्षेत्रफल = h²/√3। जैसे h = 9 ⇒ 81/√3 = 27√3।</li>\n<li><b>भुजाओं का अनुपात दिया हो:</b> 3k, 4k, 5k ⇒ क्षेत्रफल 6k²। परिमाप 144 ⇒ k = 12 ⇒ 6 × 144 = 864।</li>\n<li><b>आयत:</b> (l + b)² − (l² + b²) = 2 × क्षेत्रफल — परिमाप व विकर्ण से क्षेत्रफल सीधे।</li>\n<li><b>वर्ग:</b> दो वर्गों के विकर्णों/भुजाओं/परिमापों का अनुपात m : n हो तो क्षेत्रफल m² : n²।</li>\n<li><b>अर्धवृत्त का परिमाप</b> = 36r/7, चतुर्थांश = 25r/7 — सीधे लगाएँ।</li>\n<li><b>वलय:</b> π(R + r)(R − r) — गुणनखंड से गणना छोटी होती है। रास्ता चौड़ाई w हो तो वलय = πw(2r + w) = (औसत परिधि) × w।</li>\n<li><b>घड़ी की सुई:</b> मिनट की सुई 1 मिनट में 6°, घंटे की सुई 1 मिनट में ½°। 15 मिनट = चौथाई वृत्त, 20 मिनट = 1/3, 10 मिनट = 1/6।</li>\n<li><b>दो पहिये:</b> समान दूरी पर चक्कर परिधि (त्रिज्या) के व्युत्क्रमानुपाती। आगे का पहिया आधी परिधि का हो तो वह दुगुने चक्कर लगाता है।</li>\n<li><b>चक्कर प्रति मिनट:</b> गति (किमी/घंटा) × 1000 ÷ 60 ÷ परिधि (मी)।</li>\n<li><b>रास्ते की ट्रिक:</b> बाहर रास्ता = 2w(l + b + 2w), अंदर रास्ता = 2w(l + b − 2w), क्रॉस-रास्ते = w(l + b − w)। आम गलती — अंदर के रास्ते में कोनों को दो बार गिनना (विकल्पों में यही गलत उत्तर रखा जाता है)।</li>\n<li><b>प्रतिशत:</b> x% वृद्धि ⇒ 2x + x²/100; 10% ⇒ 21%, 20% ⇒ 44%, 25% ⇒ 56.25%, 50% ⇒ 125%, 100% (दुगुनी) ⇒ 300%। कमी: 10% ⇒ 19%, 20% ⇒ 36%, 50% ⇒ 75%।</li>\n<li><b>लंबाई +x%, चौड़ाई −x%</b> ⇒ क्षेत्रफल सदैव x²/100 % <b>घटता</b> है (कभी स्थिर नहीं रहता)।</li>\n<li><b>परिधि x% बढ़े</b> तो त्रिज्या भी x% बढ़ती है, अतः क्षेत्रफल 2x + x²/100 % बढ़ता है।</li>\n<li><b>समान परिमाप p:</b> वृत्त का क्षेत्रफल = p²/(4π), वर्ग का = p²/16; अनुपात = 4 : π = 14 : 11 (π = 22/7)। अर्थात् वृत्त लगभग 27% अधिक।</li>\n<li><b>दो वृत्तों के योग के बराबर वृत्त:</b> R² = r<sub>1</sub>² + r<sub>2</sub>² — त्रिज्याएँ 6 व 8 ⇒ R = 10 (पाइथागोरस जैसा)।</li>\n<li><b>हेक्टेयर रूपांतरण:</b> मी² को 10,000 से भाग = हेक्टेयर; 100 से भाग = एयर। 1 हेक्टेयर का वर्ग = 100 मी भुजा; परिमाप 400 मी।</li>\n<li><b>सबसे बड़ी टाइल</b> = HCF, <b>सबसे छोटा वर्ग जिसमें आयताकार टाइलें पूरी बैठें</b> = LCM।</li>\n<li><b>नियत परिमाप पर अधिकतम क्षेत्रफल</b> = (परिमाप/4)² (वर्ग)। नियत क्षेत्रफल पर न्यूनतम परिमाप भी वर्ग का होता है।</li>\n<li><b>विकल्प-विलोपन:</b> π = 22/7 वाले उत्तर प्रायः 11 या 22 से विभाज्य होते हैं (154, 616, 1386, 231, 77)। जो विकल्प 11 से न बँटे वह प्रायः गलत होता है।</li>\n</ul>\n  ",
  questions: [
    {"q":"एक त्रिभुज की भुजाएँ 13 सेमी, 14 सेमी और 15 सेमी हैं। इसका क्षेत्रफल कितना है?","o":["84 वर्ग सेमी","72 वर्ग सेमी","96 वर्ग सेमी","91 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: तीनों भुजाएँ दी हैं, अतः हीरोन सूत्र: क्षेत्रफल = √[s(s−a)(s−b)(s−c)], जहाँ s = (a+b+c)/2<br>चरण 2: s = (13 + 14 + 15)/2 = 42/2 = 21<br>चरण 3: s−a = 8, s−b = 7, s−c = 6<br>चरण 4: क्षेत्रफल = √(21 × 8 × 7 × 6) = √7056 = 84<br>अतः उत्तर = <b>84 वर्ग सेमी</b><br><b>शॉर्टकट:</b> 13-14-15 त्रिभुज को 14 आधार पर ऊँचाई 12 के दो समकोण त्रिभुजों (5-12-13 और 9-12-15) में बाँटें: ½ × 14 × 12 = 84।<br><b>ध्यान दें:</b> इस त्रिभुज का क्षेत्रफल याद रखें — परीक्षा में बार-बार आता है।"},
    {"q":"एक समबाहु त्रिभुज का क्षेत्रफल 16√3 वर्ग सेमी है। उसकी भुजा कितनी है?","o":["4 सेमी","8 सेमी","6 सेमी","16 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज का क्षेत्रफल = (√3/4)a²<br>चरण 2: (√3/4)a² = 16√3 ⇒ a² = 16 × 4 = 64<br>चरण 3: a = √64 = 8<br>अतः उत्तर = <b>8 सेमी</b><br><b>ध्यान दें:</b> a² = 64 पर रुककर 64 या आधा करके 4 चुनने की गलती न करें।"},
    {"q":"एक समबाहु त्रिभुज की ऊँचाई 6√3 सेमी है। उसका क्षेत्रफल कितना है?","o":["18√3 वर्ग सेमी","72√3 वर्ग सेमी","36√3 वर्ग सेमी","24√3 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज की ऊँचाई h = (√3/2)a<br>चरण 2: (√3/2)a = 6√3 ⇒ a = 12 सेमी<br>चरण 3: क्षेत्रफल = (√3/4) × 12² = (√3/4) × 144 = 36√3<br>अतः उत्तर = <b>36√3 वर्ग सेमी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = h²/√3 = 108/√3 = 36√3।<br><b>ध्यान दें:</b> ½ × 12 × 6√3 = 36√3 — ½ भूलने पर 72√3 (विकल्प B) आता है।"},
    {"q":"एक समद्विबाहु त्रिभुज की बराबर भुजाएँ 10 सेमी और आधार 12 सेमी है। उसका क्षेत्रफल कितना है?","o":["60 वर्ग सेमी","40 वर्ग सेमी","36 वर्ग सेमी","48 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: समद्विबाहु त्रिभुज में शीर्ष से आधार पर डाला लंब आधार को दो बराबर भागों (6 + 6) में बाँटता है।<br>चरण 2: पाइथागोरस से ऊँचाई h = √(10² − 6²) = √(100 − 36) = √64 = 8 सेमी<br>चरण 3: क्षेत्रफल = ½ × आधार × ऊँचाई = ½ × 12 × 8 = 48<br>अतः उत्तर = <b>48 वर्ग सेमी</b><br><b>शॉर्टकट:</b> सूत्र (b/4)√(4a² − b²) = (12/4)√(400 − 144) = 3 × 16 = 48।<br><b>ध्यान दें:</b> ½ × 12 × 10 = 60 (विकल्प A) गलत है — 10 भुजा है, ऊँचाई नहीं।"},
    {"q":"एक समकोण त्रिभुज का कर्ण 25 सेमी और एक भुजा 7 सेमी है। त्रिभुज का परिमाप कितना है?","o":["56 सेमी","62 सेमी","60 सेमी","54 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समकोण त्रिभुज में (कर्ण)² = (आधार)² + (लंब)²<br>चरण 2: तीसरी भुजा = √(25² − 7²) = √(625 − 49) = √576 = 24 सेमी<br>चरण 3: परिमाप = 7 + 24 + 25 = 56<br>अतः उत्तर = <b>56 सेमी</b><br><b>शॉर्टकट:</b> 7-24-25 पाइथागोरियन त्रिक याद रखें।"},
    {"q":"एक त्रिभुज की भुजाओं का अनुपात 3 : 4 : 5 है और परिमाप 144 सेमी है। उसका क्षेत्रफल कितना है?","o":["432 वर्ग सेमी","864 वर्ग सेमी","1296 वर्ग सेमी","720 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: भुजाएँ 3k, 4k, 5k ⇒ परिमाप = 12k = 144 ⇒ k = 12<br>चरण 2: भुजाएँ = 36, 48, 60 सेमी<br>चरण 3: 36² + 48² = 1296 + 2304 = 3600 = 60², अतः यह समकोण त्रिभुज है।<br>चरण 4: क्षेत्रफल = ½ × 36 × 48 = 864<br>अतः उत्तर = <b>864 वर्ग सेमी</b><br><b>शॉर्टकट:</b> 3:4:5 त्रिभुज का क्षेत्रफल = 6k² = 6 × 144 = 864।<br><b>ध्यान दें:</b> ½ गुणा भूलने पर 1728, और k² की जगह k लेने जैसी गलतियाँ होती हैं।"},
    {"q":"एक आयत की लंबाई और चौड़ाई का अनुपात 4 : 3 है और उसका विकर्ण 50 मी है। आयत का क्षेत्रफल कितना है?","o":["1000 वर्ग मी","1500 वर्ग मी","1200 वर्ग मी","1400 वर्ग मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: लंबाई = 4k, चौड़ाई = 3k<br>चरण 2: विकर्ण = √(16k² + 9k²) = 5k = 50 ⇒ k = 10<br>चरण 3: लंबाई = 40 मी, चौड़ाई = 30 मी<br>चरण 4: क्षेत्रफल = 40 × 30 = 1200<br>अतः उत्तर = <b>1200 वर्ग मी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = 12k² = 12 × 100 = 1200।"},
    {"q":"एक आयत का परिमाप 46 मी और विकर्ण 17 मी है। आयत का क्षेत्रफल कितना है?","o":["136 वर्ग मी","110 वर्ग मी","150 वर्ग मी","120 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: परिमाप 2(l + b) = 46 ⇒ l + b = 23<br>चरण 2: विकर्ण² = l² + b² = 17² = 289<br>चरण 3: (l + b)² = l² + b² + 2lb ⇒ 529 = 289 + 2lb<br>चरण 4: 2lb = 240 ⇒ lb = 120<br>अतः उत्तर = <b>120 वर्ग मी</b><br><b>शॉर्टकट:</b> l, b = 15 और 8 (8-15-17 त्रिक), क्षेत्रफल = 120।<br><b>ध्यान दें:</b> 2lb = 240 को ही क्षेत्रफल मान लेना आम गलती है।"},
    {"q":"एक वर्ग का विकर्ण 12√2 सेमी है। उसका परिमाप कितना है?","o":["48 सेमी","36 सेमी","24√2 सेमी","60 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: वर्ग का विकर्ण d = a√2<br>चरण 2: a = d/√2 = 12√2/√2 = 12 सेमी<br>चरण 3: परिमाप = 4a = 4 × 12 = 48<br>अतः उत्तर = <b>48 सेमी</b><br><b>ध्यान दें:</b> 24√2 (विकल्प C) = 2 × विकर्ण है, परिमाप नहीं।"},
    {"q":"दो वर्गों के विकर्णों का अनुपात 2 : 3 है। उनके क्षेत्रफलों का अनुपात क्या होगा?","o":["2 : 3","4 : 9","√2 : √3","8 : 27"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग का क्षेत्रफल = d²/2<br>चरण 2: अनुपात = (d₁²/2) : (d₂²/2) = d₁² : d₂²<br>चरण 3: = 2² : 3² = 4 : 9<br>अतः उत्तर = <b>4 : 9</b><br><b>शॉर्टकट:</b> समरूप आकृतियों में क्षेत्रफल का अनुपात = (किसी भी रेखीय माप का अनुपात)²।<br><b>ध्यान दें:</b> 2 : 3 रेखीय अनुपात है; 8 : 27 घन (आयतन) का अनुपात होता।"},
    {"q":"एक समचतुर्भुज के विकर्ण 16 सेमी और 30 सेमी हैं। उसका परिमाप कितना है?","o":["92 सेमी","60 सेमी","68 सेमी","46 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: समचतुर्भुज के विकर्ण एक-दूसरे को समकोण पर समद्विभाजित करते हैं।<br>चरण 2: आधे विकर्ण = 8 सेमी और 15 सेमी<br>चरण 3: भुजा = √(8² + 15²) = √(64 + 225) = √289 = 17 सेमी<br>चरण 4: परिमाप = 4 × 17 = 68<br>अतः उत्तर = <b>68 सेमी</b><br><b>शॉर्टकट:</b> परिमाप = 2√(d₁² + d₂²) = 2√(256 + 900) = 2 × 34 = 68।<br><b>ध्यान दें:</b> पूरे विकर्ण 16 और 30 से भुजा निकालने पर 34 आता है — आधे लेना ज़रूरी है।"},
    {"q":"एक समचतुर्भुज की भुजा 10 सेमी और एक विकर्ण 12 सेमी है। उसका क्षेत्रफल कितना है?","o":["120 वर्ग सेमी","192 वर्ग सेमी","48 वर्ग सेमी","96 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: विकर्ण समकोण पर समद्विभाजित करते हैं; एक विकर्ण का आधा = 6 सेमी<br>चरण 2: दूसरे विकर्ण का आधा = √(10² − 6²) = √64 = 8 ⇒ दूसरा विकर्ण = 16 सेमी<br>चरण 3: क्षेत्रफल = ½ × d₁ × d₂ = ½ × 12 × 16 = 96<br>अतः उत्तर = <b>96 वर्ग सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर 192 (विकल्प B) आता है।"},
    {"q":"एक समांतर चतुर्भुज की आसन्न भुजाएँ 12 सेमी और 8 सेमी हैं। लंबी भुजाओं के बीच की दूरी 6 सेमी है। छोटी भुजाओं के बीच की दूरी कितनी है?","o":["9 सेमी","4 सेमी","16 सेमी","12 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समांतर चतुर्भुज का क्षेत्रफल = आधार × उस आधार पर ऊँचाई<br>चरण 2: लंबी भुजा (12) को आधार मानें: क्षेत्रफल = 12 × 6 = 72 वर्ग सेमी<br>चरण 3: छोटी भुजा (8) को आधार मानें: 8 × h = 72 ⇒ h = 9 सेमी<br>अतः उत्तर = <b>9 सेमी</b><br><b>ध्यान दें:</b> छोटी भुजाओं के बीच की दूरी बड़ी होती है; 4 सेमी (विकल्प B) उल्टा अनुपात लेने से आता है।"},
    {"q":"एक समलंब चतुर्भुज की समांतर भुजाएँ 20 सेमी और 12 सेमी हैं तथा उनके बीच की दूरी 7 सेमी है। क्षेत्रफल कितना है?","o":["224 वर्ग सेमी","112 वर्ग सेमी","140 वर्ग सेमी","84 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समलंब का क्षेत्रफल = ½ × (समांतर भुजाओं का योग) × उनके बीच की दूरी<br>चरण 2: = ½ × (20 + 12) × 7 = ½ × 32 × 7<br>चरण 3: = 16 × 7 = 112<br>अतः उत्तर = <b>112 वर्ग सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर 224 (विकल्प A) आता है।"},
    {"q":"एक समलंब का क्षेत्रफल 360 वर्ग सेमी और ऊँचाई 12 सेमी है। यदि एक समांतर भुजा 22 सेमी हो, तो दूसरी समांतर भुजा कितनी है?","o":["30 सेमी","16 सेमी","38 सेमी","28 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = ½ × (a + b) × h<br>चरण 2: 360 = ½ × (a + b) × 12 ⇒ a + b = 360 × 2/12 = 60<br>चरण 3: दूसरी भुजा = 60 − 22 = 38<br>अतः उत्तर = <b>38 सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर a + b = 30 मानकर 8, या 30 − 22 जैसी गलत गणना होती है।"},
    {"q":"एक समलंब चतुर्भुज की समांतर भुजाएँ 25 मी और 11 मी तथा असमांतर भुजाएँ 15 मी और 13 मी हैं। समलंब का क्षेत्रफल कितना है?","o":["252 वर्ग मी","180 वर्ग मी","234 वर्ग मी","216 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: छोटी समांतर भुजा (11) के सिरे से असमांतर भुजा 13 के समांतर रेखा खींचें। इससे एक समांतर चतुर्भुज और एक त्रिभुज बनता है।<br>चरण 2: त्रिभुज की भुजाएँ = 25 − 11 = 14, 15 और 13 मी<br>चरण 3: हीरोन से: s = (14 + 15 + 13)/2 = 21; क्षेत्रफल = √(21 × 7 × 6 × 8) = √7056 = 84<br>चरण 4: त्रिभुज की ऊँचाई (= समलंब की ऊँचाई) = 2 × 84/14 = 12 मी<br>चरण 5: समलंब का क्षेत्रफल = ½ × (25 + 11) × 12 = 18 × 12 = 216<br>अतः उत्तर = <b>216 वर्ग मी</b><br><b>ध्यान दें:</b> केवल त्रिभुज का क्षेत्रफल 84 निकालकर रुकना नहीं है; ऊँचाई निकालकर पूरे समलंब का क्षेत्रफल चाहिए।"},
    {"q":"एक वृत्त की परिधि 88 सेमी है। उसका क्षेत्रफल कितना है? (π = 22/7)","o":["616 वर्ग सेमी","154 वर्ग सेमी","1232 वर्ग सेमी","308 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: परिधि = 2πr ⇒ 2 × 22/7 × r = 88<br>चरण 2: r = 88 × 7/44 = 14 सेमी<br>चरण 3: क्षेत्रफल = πr² = 22/7 × 14 × 14 = 22 × 28 = 616<br>अतः उत्तर = <b>616 वर्ग सेमी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = C²/(4π) = 7744 × 7/88 = 616।"},
    {"q":"एक वृत्त का क्षेत्रफल 154 वर्ग सेमी है। उसकी परिधि कितनी है? (π = 22/7)","o":["22 सेमी","44 सेमी","88 सेमी","14 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: πr² = 154 ⇒ r² = 154 × 7/22 = 49<br>चरण 2: r = 7 सेमी<br>चरण 3: परिधि = 2πr = 2 × 22/7 × 7 = 44<br>अतः उत्तर = <b>44 सेमी</b><br><b>ध्यान दें:</b> 154 वर्ग सेमी ⇔ r = 7 — यह जोड़ी याद रखें।"},
    {"q":"14 सेमी त्रिज्या वाले अर्धवृत्त का परिमाप कितना है? (π = 22/7)","o":["44 सेमी","58 सेमी","72 सेमी","88 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: अर्धवृत्त का परिमाप = वक्र भाग (πr) + व्यास (2r)<br>चरण 2: πr = 22/7 × 14 = 44 सेमी<br>चरण 3: 2r = 28 सेमी<br>चरण 4: परिमाप = 44 + 28 = 72<br>अतः उत्तर = <b>72 सेमी</b><br><b>शॉर्टकट:</b> परिमाप = r(π + 2) = 14 × 36/7 = 72।<br><b>ध्यान दें:</b> केवल चाप 44 (विकल्प A) लेना आम गलती है — सीधा किनारा (व्यास) भी जोड़ें।"},
    {"q":"दो संकेंद्री वृत्तों की त्रिज्याएँ 21 सेमी और 14 सेमी हैं। उनके बीच के वलय का क्षेत्रफल कितना है? (π = 22/7)","o":["462 वर्ग सेमी","616 वर्ग सेमी","1386 वर्ग सेमी","770 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: वलय का क्षेत्रफल = πR² − πr² = π(R + r)(R − r)<br>चरण 2: R + r = 35, R − r = 7<br>चरण 3: क्षेत्रफल = 22/7 × 35 × 7 = 22 × 35 = 770<br>अतः उत्तर = <b>770 वर्ग सेमी</b><br><b>ध्यान दें:</b> 1386 (विकल्प C) केवल बड़े वृत्त का क्षेत्रफल है; 616 केवल छोटे का।"},
    {"q":"एक वृत्ताकार दौड़-पथ (ट्रैक) की भीतरी परिधि 440 मी है और ट्रैक 14 मी चौड़ा है। ट्रैक का क्षेत्रफल कितना है? (π = 22/7)","o":["6776 वर्ग मी","6160 वर्ग मी","7392 वर्ग मी","5544 वर्ग मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: भीतरी परिधि 2πr = 440 ⇒ r = 440 × 7/44 = 70 मी<br>चरण 2: बाहरी त्रिज्या R = 70 + 14 = 84 मी<br>चरण 3: ट्रैक का क्षेत्रफल = π(R + r)(R − r) = 22/7 × 154 × 14<br>चरण 4: = 22 × 22 × 14 = 6776<br>अतः उत्तर = <b>6776 वर्ग मी</b><br><b>शॉर्टकट:</b> ट्रैक क्षेत्रफल = (भीतरी परिधि × चौड़ाई) + πw² = 440 × 14 + 22/7 × 196 = 6160 + 616 = 6776।<br><b>ध्यान दें:</b> 6160 (विकल्प B) केवल परिधि × चौड़ाई है — πw² भाग छूट गया।"},
    {"q":"14 सेमी त्रिज्या वाले वृत्त के उस त्रिज्यखंड का क्षेत्रफल कितना है जिसका केंद्रीय कोण 45° है? (π = 22/7)","o":["154 वर्ग सेमी","77 वर्ग सेमी","38.5 वर्ग सेमी","88 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: त्रिज्यखंड का क्षेत्रफल = (θ/360°) × πr²<br>चरण 2: πr² = 22/7 × 14 × 14 = 616 वर्ग सेमी<br>चरण 3: (45/360) × 616 = 616/8 = 77<br>अतः उत्तर = <b>77 वर्ग सेमी</b><br><b>ध्यान दें:</b> 45° = वृत्त का 1/8 भाग; 154 (विकल्प A) 1/4 भाग (90°) है।"},
    {"q":"21 सेमी त्रिज्या वाले वृत्त में 120° केंद्रीय कोण बनाने वाले चाप की लंबाई कितनी है? (π = 22/7)","o":["22 सेमी","66 सेमी","44 सेमी","88 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: चाप की लंबाई = (θ/360°) × 2πr<br>चरण 2: परिधि = 2 × 22/7 × 21 = 132 सेमी<br>चरण 3: चाप = (120/360) × 132 = 132/3 = 44<br>अतः उत्तर = <b>44 सेमी</b>"},
    {"q":"14 सेमी त्रिज्या वाले वृत्त के चतुर्थांश (90° त्रिज्यखंड) का परिमाप कितना है? (π = 22/7)","o":["22 सेमी","36 सेमी","64 सेमी","50 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: चतुर्थांश का परिमाप = चाप + 2 त्रिज्याएँ<br>चरण 2: पूरी परिधि = 2 × 22/7 × 14 = 88 ⇒ चाप = 88/4 = 22 सेमी<br>चरण 3: परिमाप = 22 + 14 + 14 = 50<br>अतः उत्तर = <b>50 सेमी</b><br><b>ध्यान दें:</b> केवल चाप 22 (विकल्प A) या एक ही त्रिज्या जोड़कर 36 (विकल्प B) लेना गलत है।"},
    {"q":"35 सेमी त्रिज्या वाला एक पहिया 1000 चक्कर लगाता है। वह कितनी दूरी तय करेगा? (π = 22/7)","o":["2.2 किमी","1.1 किमी","4.4 किमी","3.5 किमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक चक्कर में दूरी = पहिये की परिधि = 2πr<br>चरण 2: परिधि = 2 × 22/7 × 35 = 220 सेमी<br>चरण 3: 1000 चक्कर में दूरी = 220 × 1000 = 2,20,000 सेमी<br>चरण 4: 1 किमी = 1,00,000 सेमी ⇒ दूरी = 2.2 किमी<br>अतः उत्तर = <b>2.2 किमी</b><br><b>ध्यान दें:</b> परिधि में 2 भूलने पर (πr) 1.1 किमी (विकल्प B) आता है।"},
    {"q":"1.4 मी व्यास वाले पहिये को 1.1 किमी दूरी तय करने में कितने चक्कर लगाने होंगे? (π = 22/7)","o":["500","250","125","350"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक चक्कर = परिधि = πd = 22/7 × 1.4 = 4.4 मी<br>चरण 2: कुल दूरी = 1.1 किमी = 1100 मी<br>चरण 3: चक्कर = 1100 ÷ 4.4 = 250<br>अतः उत्तर = <b>250</b><br><b>ध्यान दें:</b> 1.4 को त्रिज्या मानने पर परिधि 8.8 और चक्कर 125 (विकल्प C) आते हैं; व्यास दिया है।"},
    {"q":"70 सेमी व्यास वाले पहियों की एक गाड़ी 66 किमी/घंटा की चाल से चल रही है। पहिया प्रति मिनट कितने चक्कर लगाता है? (π = 22/7)","o":["250","1000","500","300"],"a":2,"e":"<b>हल:</b><br>चरण 1: चाल = 66 किमी/घंटा = 66000 मी/घंटा<br>चरण 2: प्रति मिनट दूरी = 66000 ÷ 60 = 1100 मी<br>चरण 3: पहिये की परिधि = πd = 22/7 × 0.7 = 2.2 मी<br>चरण 4: प्रति मिनट चक्कर = 1100 ÷ 2.2 = 500<br>अतः उत्तर = <b>500</b><br><b>ध्यान दें:</b> 70 सेमी को त्रिज्या मानने पर परिधि 4.4 मी व चक्कर 250 (विकल्प A) आते हैं।"},
    {"q":"60 मी × 40 मी के एक आयताकार बगीचे के बाहर चारों ओर 5 मी चौड़ा रास्ता है। रास्ते का क्षेत्रफल कितना है?","o":["1000 वर्ग मी","1200 वर्ग मी","900 वर्ग मी","1100 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: रास्ता बाहर है, अतः बाहरी आयत = (60 + 2×5) × (40 + 2×5) = 70 × 50<br>चरण 2: बाहरी क्षेत्रफल = 3500 वर्ग मी; बगीचा = 60 × 40 = 2400 वर्ग मी<br>चरण 3: रास्ता = 3500 − 2400 = 1100<br>अतः उत्तर = <b>1100 वर्ग मी</b><br><b>शॉर्टकट:</b> बाहरी रास्ता = 2w(l + b + 2w) = 10 × (100 + 10) = 1100।<br><b>ध्यान दें:</b> दोनों ओर चौड़ाई जोड़ें (+10), केवल +5 नहीं।"},
    {"q":"50 मी × 30 मी के एक आयताकार मैदान के अंदर चारों ओर 2.5 मी चौड़ा रास्ता है। रास्ते का क्षेत्रफल कितना है?","o":["375 वर्ग मी","400 वर्ग मी","350 वर्ग मी","425 वर्ग मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: रास्ता अंदर है, अतः भीतरी आयत = (50 − 2×2.5) × (30 − 2×2.5) = 45 × 25<br>चरण 2: भीतरी क्षेत्रफल = 1125 वर्ग मी; मैदान = 50 × 30 = 1500 वर्ग मी<br>चरण 3: रास्ता = 1500 − 1125 = 375<br>अतः उत्तर = <b>375 वर्ग मी</b><br><b>शॉर्टकट:</b> भीतरी रास्ता = 2w(l + b − 2w) = 5 × (80 − 5) = 375।<br><b>ध्यान दें:</b> 2w(l + b) = 400 (विकल्प B) में चारों कोने दो बार गिने जाते हैं।"},
    {"q":"80 मी × 60 मी के एक आयताकार लॉन के बीचोबीच भुजाओं के समांतर 10 मी चौड़े दो क्रॉस-रास्ते हैं। ₹3 प्रति वर्ग मी की दर से रास्तों पर बजरी बिछाने का खर्च कितना होगा?","o":["₹4200","₹3900","₹1300","₹3600"],"a":1,"e":"<b>हल:</b><br>चरण 1: लंबाई के समांतर रास्ता = 80 × 10 = 800 वर्ग मी<br>चरण 2: चौड़ाई के समांतर रास्ता = 60 × 10 = 600 वर्ग मी<br>चरण 3: बीच का चौराहा (10 × 10 = 100) दो बार गिना गया ⇒ कुल = 800 + 600 − 100 = 1300 वर्ग मी<br>चरण 4: खर्च = 1300 × 3 = ₹3900<br>अतः उत्तर = <b>₹3900</b><br><b>शॉर्टकट:</b> क्रॉस-रास्ते = w(l + b − w) = 10 × 130 = 1300।<br><b>ध्यान दें:</b> 100 न घटाने पर ₹4200 (विकल्प A); खर्च की जगह क्षेत्रफल 1300 लिखना विकल्प C है।"},
    {"q":"6 मी लंबे और 4.5 मी चौड़े कमरे के फर्श पर 30 सेमी भुजा वाली वर्गाकार टाइलें लगानी हैं। कितनी टाइलें लगेंगी?","o":["270","250","300","350"],"a":2,"e":"<b>हल:</b><br>चरण 1: एक ही इकाई लें: कमरा = 600 सेमी × 450 सेमी = 2,70,000 वर्ग सेमी<br>चरण 2: एक टाइल = 30 × 30 = 900 वर्ग सेमी<br>चरण 3: टाइलें = 2,70,000 ÷ 900 = 300<br>अतः उत्तर = <b>300</b><br><b>शॉर्टकट:</b> (600/30) × (450/30) = 20 × 15 = 300।"},
    {"q":"16.8 मी लंबे और 12 मी चौड़े आँगन में एक समान आकार की सबसे बड़ी वर्गाकार टाइलें लगानी हैं। न्यूनतम कितनी टाइलें लगेंगी?","o":["24","40","70","35"],"a":3,"e":"<b>हल:</b><br>चरण 1: सबसे बड़ी वर्गाकार टाइल की भुजा = HCF(लंबाई, चौड़ाई)<br>चरण 2: HCF(1680 सेमी, 1200 सेमी) = 240 सेमी<br>चरण 3: लंबाई में टाइलें = 1680/240 = 7; चौड़ाई में = 1200/240 = 5<br>चरण 4: कुल टाइलें = 7 × 5 = 35<br>अतः उत्तर = <b>35</b><br><b>ध्यान दें:</b> \"सबसे बड़ी टाइल\" ⇒ HCF, LCM नहीं।"},
    {"q":"एक वर्गाकार खेत का क्षेत्रफल 4 हेक्टेयर है। ₹15 प्रति मीटर की दर से उसके चारों ओर बाड़ लगाने का खर्च कितना होगा?","o":["₹12000","₹6000","₹24000","₹3000"],"a":0,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10000 वर्ग मी ⇒ 4 हेक्टेयर = 40000 वर्ग मी<br>चरण 2: वर्ग की भुजा = √40000 = 200 मी<br>चरण 3: परिमाप = 4 × 200 = 800 मी<br>चरण 4: बाड़ का खर्च = 800 × 15 = ₹12000<br>अतः उत्तर = <b>₹12000</b><br><b>ध्यान दें:</b> बाड़ परिमाप पर लगती है, क्षेत्रफल पर नहीं।"},
    {"q":"एक वृत्ताकार खेत का क्षेत्रफल 1386 वर्ग मी है। ₹4.50 प्रति मीटर की दर से उसके चारों ओर बाड़ लगाने का खर्च कितना होगा? (π = 22/7)","o":["₹297","₹594","₹660","₹462"],"a":1,"e":"<b>हल:</b><br>चरण 1: πr² = 1386 ⇒ r² = 1386 × 7/22 = 441 ⇒ r = 21 मी<br>चरण 2: परिधि = 2πr = 2 × 22/7 × 21 = 132 मी<br>चरण 3: खर्च = 132 × 4.50 = ₹594<br>अतः उत्तर = <b>₹594</b><br><b>ध्यान दें:</b> 2 भूलने पर (πr = 66) खर्च ₹297 (विकल्प A) आता है।"},
    {"q":"एक कमरा 12 मी लंबा, 10 मी चौड़ा और 5 मी ऊँचा है। ₹20 प्रति वर्ग मी की दर से उसकी चारों दीवारों की रंगाई का खर्च कितना होगा?","o":["₹2200","₹6800","₹4400","₹5200"],"a":2,"e":"<b>हल:</b><br>चरण 1: चार दीवारों का क्षेत्रफल = 2h(l + b)<br>चरण 2: = 2 × 5 × (12 + 10) = 10 × 22 = 220 वर्ग मी<br>चरण 3: खर्च = 220 × 20 = ₹4400<br>अतः उत्तर = <b>₹4400</b><br><b>ध्यान दें:</b> 2 भूलने पर ₹2200 (विकल्प A); छत/फर्श जोड़ना प्रश्न में नहीं माँगा।"},
    {"q":"15 मी × 8 मी के कमरे में 75 सेमी चौड़ा कालीन बिछाना है। ₹25 प्रति मीटर की दर से कालीन का खर्च कितना होगा?","o":["₹3000","₹2500","₹4800","₹4000"],"a":3,"e":"<b>हल:</b><br>चरण 1: कमरे का क्षेत्रफल = 15 × 8 = 120 वर्ग मी<br>चरण 2: कालीन की चौड़ाई = 75 सेमी = 0.75 मी<br>चरण 3: कालीन की लंबाई = 120 ÷ 0.75 = 160 मी<br>चरण 4: खर्च = 160 × 25 = ₹4000<br>अतः उत्तर = <b>₹4000</b><br><b>ध्यान दें:</b> दर प्रति मीटर (लंबाई) है, इसलिए क्षेत्रफल × दर = ₹3000 (विकल्प A) गलत है।"},
    {"q":"यदि किसी वर्ग की भुजा 20% बढ़ा दी जाए, तो उसका क्षेत्रफल कितने प्रतिशत बढ़ेगा?","o":["44%","40%","20%","21%"],"a":0,"e":"<b>हल:</b><br>चरण 1: भुजा a ⇒ नई भुजा 1.2a<br>चरण 2: नया क्षेत्रफल = (1.2a)² = 1.44a²<br>चरण 3: वृद्धि = 1.44a² − a² = 0.44a² = 44%<br>अतः उत्तर = <b>44%</b><br><b>शॉर्टकट:</b> क्रमिक प्रतिशत सूत्र: x + x + x²/100 = 20 + 20 + 4 = 44%।<br><b>ध्यान दें:</b> 40% (विकल्प B) में x²/100 = 4 छूट गया।"},
    {"q":"यदि किसी वृत्त की त्रिज्या 10% घटा दी जाए, तो उसका क्षेत्रफल कितने प्रतिशत घटेगा?","o":["20%","19%","10%","21%"],"a":1,"e":"<b>हल:</b><br>चरण 1: त्रिज्या r ⇒ नई त्रिज्या 0.9r<br>चरण 2: नया क्षेत्रफल = π(0.9r)² = 0.81πr²<br>चरण 3: कमी = 1 − 0.81 = 0.19 = 19%<br>अतः उत्तर = <b>19%</b><br><b>शॉर्टकट:</b> −10 − 10 + (100/100) = −19%।<br><b>ध्यान दें:</b> 20% (विकल्प A) में x²/100 भाग नहीं जोड़ा गया।"},
    {"q":"एक आयत की लंबाई 20% बढ़ाई जाए और चौड़ाई 20% घटाई जाए, तो उसके क्षेत्रफल में क्या परिवर्तन होगा?","o":["कोई परिवर्तन नहीं","4% वृद्धि","4% कमी","2% कमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: नई लंबाई = 1.2l, नई चौड़ाई = 0.8b<br>चरण 2: नया क्षेत्रफल = 1.2 × 0.8 × lb = 0.96lb<br>चरण 3: परिवर्तन = 0.96 − 1 = −0.04 ⇒ 4% कमी<br>अतः उत्तर = <b>4% कमी</b><br><b>शॉर्टकट:</b> x + y + xy/100 = 20 − 20 − 4 = −4%।<br><b>ध्यान दें:</b> +20 और −20 से \"कोई परिवर्तन नहीं\" मानना आम गलती है।"},
    {"q":"किसी आयत की लंबाई 25% बढ़ा दी जाए, तो क्षेत्रफल अपरिवर्तित रखने के लिए चौड़ाई कितने प्रतिशत घटानी होगी?","o":["25%","15%","30%","20%"],"a":3,"e":"<b>हल:</b><br>चरण 1: नई लंबाई = 1.25l; क्षेत्रफल समान रखने के लिए नई चौड़ाई = lb/(1.25l) = 0.8b<br>चरण 2: चौड़ाई में कमी = 1 − 0.8 = 0.2 = 20%<br>अतः उत्तर = <b>20%</b><br><b>शॉर्टकट:</b> कमी% = 100x/(100 + x) = 2500/125 = 20%। (25% = 1/4 ⇒ कमी = 1/5 = 20%)<br><b>ध्यान दें:</b> 25% (विकल्प A) उतना ही घटाने से क्षेत्रफल घट जाता है (1.25 × 0.75 = 0.9375)।"},
    {"q":"एक वृत्त और एक वर्ग दोनों का परिमाप 88 सेमी है। उनके क्षेत्रफलों का अंतर कितना है? (π = 22/7)","o":["132 वर्ग सेमी","110 वर्ग सेमी","154 वर्ग सेमी","88 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: वृत्त: 2πr = 88 ⇒ r = 14 सेमी; क्षेत्रफल = 22/7 × 196 = 616 वर्ग सेमी<br>चरण 2: वर्ग: 4a = 88 ⇒ a = 22 सेमी; क्षेत्रफल = 484 वर्ग सेमी<br>चरण 3: अंतर = 616 − 484 = 132<br>अतः उत्तर = <b>132 वर्ग सेमी</b><br><b>ध्यान दें:</b> समान परिमाप पर वृत्त का क्षेत्रफल हमेशा वर्ग से अधिक होता है।"},
    {"q":"समान परिमाप वाले एक वृत्त और एक वर्ग के क्षेत्रफलों का अनुपात क्या है? (π = 22/7)","o":["11 : 14","14 : 11","7 : 11","22 : 7"],"a":1,"e":"<b>हल:</b><br>चरण 1: माना परिमाप = P। वृत्त: r = P/(2π), क्षेत्रफल = P²/(4π)<br>चरण 2: वर्ग: भुजा = P/4, क्षेत्रफल = P²/16<br>चरण 3: अनुपात = (1/4π) : (1/16) = 16 : 4π = 4 : π<br>चरण 4: = 4 : 22/7 = 28 : 22 = 14 : 11<br>अतः उत्तर = <b>14 : 11</b><br><b>शॉर्टकट:</b> P = 88 लें: 616 : 484 = 14 : 11।<br><b>ध्यान दें:</b> 11 : 14 (विकल्प A) उल्टा क्रम है — वृत्त का क्षेत्रफल बड़ा है।"},
    {"q":"2.5 हेक्टेयर कितने वर्ग मीटर के बराबर है?","o":["2500 वर्ग मी","250000 वर्ग मी","25000 वर्ग मी","250 वर्ग मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 100 मी × 100 मी = 10000 वर्ग मी<br>चरण 2: 2.5 हेक्टेयर = 2.5 × 10000 = 25000 वर्ग मी<br>अतः उत्तर = <b>25000 वर्ग मी</b><br><b>ध्यान दें:</b> 1 एयर (are) = 100 वर्ग मी, 1 हेक्टेयर = 100 एयर।"},
    {"q":"250 मी लंबे और 120 मी चौड़े आयताकार खेत का क्षेत्रफल हेक्टेयर में कितना है?","o":["30 हेक्टेयर","0.3 हेक्टेयर","300 हेक्टेयर","3 हेक्टेयर"],"a":3,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = 250 × 120 = 30000 वर्ग मी<br>चरण 2: 1 हेक्टेयर = 10000 वर्ग मी<br>चरण 3: 30000 ÷ 10000 = 3 हेक्टेयर<br>अतः उत्तर = <b>3 हेक्टेयर</b>"},
    {"q":"एक समबाहु त्रिभुज का परिमाप 36 सेमी है। उसका क्षेत्रफल कितना है?","o":["36√3 वर्ग सेमी","48√3 वर्ग सेमी","144√3 वर्ग सेमी","12√3 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: भुजा = 36 ÷ 3 = 12 सेमी<br>चरण 2: क्षेत्रफल = (√3/4)a² = (√3/4) × 144 = 36√3<br>अतः उत्तर = <b>36√3 वर्ग सेमी</b><br><b>ध्यान दें:</b> परिमाप 36 को भुजा मानने पर 324√3 आता है; 144√3 (विकल्प C) में ÷4 छूट गया।"},
    {"q":"14 सेमी भुजा वाले एक वर्गाकार कागज़ में से सबसे बड़ा संभव वृत्त काट लिया गया। शेष कागज़ का क्षेत्रफल कितना है? (π = 22/7)","o":["154 वर्ग सेमी","42 वर्ग सेमी","56 वर्ग सेमी","49 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग में सबसे बड़े वृत्त का व्यास = भुजा = 14 ⇒ r = 7 सेमी<br>चरण 2: वृत्त का क्षेत्रफल = 22/7 × 49 = 154 वर्ग सेमी<br>चरण 3: वर्ग का क्षेत्रफल = 14² = 196 वर्ग सेमी<br>चरण 4: शेष = 196 − 154 = 42<br>अतः उत्तर = <b>42 वर्ग सेमी</b><br><b>शॉर्टकट:</b> शेष = a²(1 − π/4) = 196 × 3/14 = 42।"},
    {"q":"24 सेमी × 14 सेमी की आयताकार शीट से सबसे बड़ा वृत्त काटने पर शेष शीट का क्षेत्रफल कितना होगा? (π = 22/7)","o":["154 वर्ग सेमी","206 वर्ग सेमी","182 वर्ग सेमी","224 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: आयत में सबसे बड़े वृत्त का व्यास = छोटी भुजा = 14 ⇒ r = 7<br>चरण 2: वृत्त का क्षेत्रफल = 22/7 × 49 = 154 वर्ग सेमी<br>चरण 3: शीट = 24 × 14 = 336 वर्ग सेमी<br>चरण 4: शेष = 336 − 154 = 182<br>अतः उत्तर = <b>182 वर्ग सेमी</b><br><b>ध्यान दें:</b> व्यास 24 (बड़ी भुजा) नहीं हो सकता — वृत्त शीट से बाहर निकल जाएगा।"},
    {"q":"10 सेमी त्रिज्या वाले वृत्त के अंदर बने सबसे बड़े वर्ग का क्षेत्रफल कितना है?","o":["100 वर्ग सेमी","400 वर्ग सेमी","314 वर्ग सेमी","200 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: वृत्त के अंदर सबसे बड़े वर्ग का विकर्ण = वृत्त का व्यास = 20 सेमी<br>चरण 2: वर्ग का क्षेत्रफल = d²/2 = 400/2 = 200<br>अतः उत्तर = <b>200 वर्ग सेमी</b><br><b>शॉर्टकट:</b> अंतर्लिखित वर्ग = 2r²।<br><b>ध्यान दें:</b> 400 (विकल्प B) वृत्त के बाहर बने (परिगत) वर्ग का क्षेत्रफल है।"},
    {"q":"एक तार को मोड़कर 484 वर्ग सेमी क्षेत्रफल का वर्ग बनाया गया है। उसी तार को मोड़कर वृत्त बनाया जाए तो वृत्त का क्षेत्रफल कितना होगा? (π = 22/7)","o":["616 वर्ग सेमी","484 वर्ग सेमी","554 वर्ग सेमी","704 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: वर्ग की भुजा = √484 = 22 सेमी ⇒ तार की लंबाई = 4 × 22 = 88 सेमी<br>चरण 2: वृत्त: 2πr = 88 ⇒ r = 14 सेमी<br>चरण 3: वृत्त का क्षेत्रफल = 22/7 × 196 = 616<br>अतः उत्तर = <b>616 वर्ग सेमी</b><br><b>ध्यान दें:</b> तार की लंबाई (परिमाप) समान रहती है, क्षेत्रफल नहीं।"},
    {"q":"28 सेमी त्रिज्या के वृत्ताकार तार को मोड़कर एक आयत बनाया गया जिसकी लंबाई और चौड़ाई का अनुपात 6 : 5 है। आयत का क्षेत्रफल कितना है? (π = 22/7)","o":["1936 वर्ग सेमी","1920 वर्ग सेमी","1980 वर्ग सेमी","1800 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: तार की लंबाई = 2πr = 2 × 22/7 × 28 = 176 सेमी<br>चरण 2: आयत का परिमाप 2(l + b) = 176 ⇒ l + b = 88<br>चरण 3: l : b = 6 : 5 ⇒ 11k = 88 ⇒ k = 8 ⇒ l = 48, b = 40<br>चरण 4: क्षेत्रफल = 48 × 40 = 1920<br>अतः उत्तर = <b>1920 वर्ग सेमी</b><br><b>ध्यान दें:</b> l + b = 176 लेना (2 से भाग भूलना) आम गलती है।"},
    {"q":"एक त्रिभुज का क्षेत्रफल 216 वर्ग सेमी है और उसके आधार व ऊँचाई का अनुपात 4 : 3 है। आधार कितना है?","o":["18 सेमी","36 सेमी","24 सेमी","12 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: आधार = 4k, ऊँचाई = 3k<br>चरण 2: ½ × 4k × 3k = 6k² = 216 ⇒ k² = 36 ⇒ k = 6<br>चरण 3: आधार = 4 × 6 = 24<br>अतः उत्तर = <b>24 सेमी</b><br><b>ध्यान दें:</b> 18 सेमी (विकल्प A) ऊँचाई है, आधार नहीं।"},
    {"q":"एक त्रिभुज का क्षेत्रफल 64 वर्ग सेमी है। उसकी भुजाओं के मध्य-बिंदुओं को मिलाने से बने त्रिभुज का क्षेत्रफल कितना होगा?","o":["32 वर्ग सेमी","8 वर्ग सेमी","48 वर्ग सेमी","16 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: मध्य-बिंदु प्रमेय: मध्य-बिंदुओं को मिलाने वाली हर रेखा तीसरी भुजा की आधी होती है।<br>चरण 2: नया त्रिभुज मूल के समरूप है, भुजा-अनुपात 1 : 2 ⇒ क्षेत्रफल-अनुपात 1 : 4<br>चरण 3: नया क्षेत्रफल = 64/4 = 16<br>अतः उत्तर = <b>16 वर्ग सेमी</b><br><b>ध्यान दें:</b> भुजाएँ आधी होने से क्षेत्रफल आधा (32) नहीं, चौथाई होता है।"},
    {"q":"एक समकोण त्रिभुज की समकोण बनाने वाली भुजाओं का अनुपात 3 : 4 है और क्षेत्रफल 216 वर्ग सेमी है। कर्ण कितना है?","o":["30 सेमी","25 सेमी","36 सेमी","40 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: भुजाएँ 3k और 4k ⇒ क्षेत्रफल = ½ × 3k × 4k = 6k²<br>चरण 2: 6k² = 216 ⇒ k² = 36 ⇒ k = 6<br>चरण 3: भुजाएँ 18 और 24 सेमी<br>चरण 4: कर्ण = √(18² + 24²) = √(324 + 576) = √900 = 30<br>अतः उत्तर = <b>30 सेमी</b><br><b>शॉर्टकट:</b> कर्ण = 5k = 30।"},
    {"q":"घड़ी की मिनट की सुई 21 सेमी लंबी है। 10 मिनट में वह कितना क्षेत्रफल घेरती है? (π = 22/7)","o":["462 वर्ग सेमी","231 वर्ग सेमी","154 वर्ग सेमी","693 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: मिनट की सुई 60 मिनट में 360° घूमती है ⇒ 1 मिनट में 6°<br>चरण 2: 10 मिनट में = 60°<br>चरण 3: क्षेत्रफल = (60/360) × πr² = (1/6) × 22/7 × 441 = 1386/6 = 231<br>अतः उत्तर = <b>231 वर्ग सेमी</b><br><b>ध्यान दें:</b> 462 (विकल्प A) 120° (20 मिनट) का क्षेत्रफल है।"},
    {"q":"एक आयत का परिमाप 60 मी है। उसका अधिकतम संभव क्षेत्रफल कितना हो सकता है?","o":["200 वर्ग मी","216 वर्ग मी","225 वर्ग मी","250 वर्ग मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: l + b = 60/2 = 30 मी<br>चरण 2: नियत योग पर गुणनफल lb तब अधिकतम होता है जब l = b, अर्थात् आयत वर्ग बने।<br>चरण 3: l = b = 15 मी ⇒ क्षेत्रफल = 15 × 15 = 225<br>अतः उत्तर = <b>225 वर्ग मी</b><br><b>ध्यान दें:</b> 216 (18 × 12) और 200 (20 × 10) संभव हैं पर अधिकतम नहीं।"},
    {"q":"एक गाड़ी के आगे के पहिये की त्रिज्या 35 सेमी और पीछे के पहिये की त्रिज्या 70 सेमी है। कितनी दूरी तय करने में आगे का पहिया पीछे वाले से 100 चक्कर अधिक लगाएगा? (π = 22/7)","o":["220 मी","880 मी","660 मी","440 मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: आगे के पहिये की परिधि = 2 × 22/7 × 35 = 220 सेमी = 2.2 मी<br>चरण 2: पीछे के पहिये की परिधि = 2 × 22/7 × 70 = 440 सेमी = 4.4 मी<br>चरण 3: दूरी d पर चक्करों का अंतर: d/2.2 − d/4.4 = 100<br>चरण 4: (2d − d)/4.4 = 100 ⇒ d/4.4 = 100 ⇒ d = 440 मी<br>अतः उत्तर = <b>440 मी</b><br><b>शॉर्टकट:</b> पीछे का पहिया दोगुना बड़ा है, अतः जितने चक्कर वह लगाता है (100), उतने ही अधिक आगे वाला लगाता है ⇒ d = 100 × 4.4 = 440 मी।<br><b>ध्यान दें:</b> 220 मी (विकल्प A) छोटे पहिये की परिधि से गुणा करने पर आता है।"},
    {"q":"एक अर्धवृत्ताकार प्लेट का परिमाप 36 सेमी है। उसकी त्रिज्या कितनी है? (π = 22/7)","o":["7 सेमी","14 सेमी","6 सेमी","9 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: अर्धवृत्त का परिमाप = πr + 2r = r(22/7 + 2) = (36/7)r<br>चरण 2: (36/7)r = 36 ⇒ r = 7<br>अतः उत्तर = <b>7 सेमी</b><br><b>ध्यान दें:</b> केवल πr = 36 लेने पर r ≈ 11.45 आता है जो विकल्पों में नहीं — व्यास जोड़ना ज़रूरी है।"},
    {"q":"एक आयताकार भूखंड का क्षेत्रफल 1 हेक्टेयर और लंबाई 125 मी है। उसका परिमाप कितना है?","o":["400 मी","410 मी","450 मी","205 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10000 वर्ग मी<br>चरण 2: चौड़ाई = 10000 ÷ 125 = 80 मी<br>चरण 3: परिमाप = 2(125 + 80) = 2 × 205 = 410<br>अतः उत्तर = <b>410 मी</b><br><b>ध्यान दें:</b> 205 मी (विकल्प D) केवल l + b है, 2 से गुणा नहीं किया।"},
    {"q":"एक त्रिभुज की भुजाएँ 9 सेमी, 10 सेमी और 17 सेमी हैं। उसका क्षेत्रफल कितना है?","o":["45 वर्ग सेमी","54 वर्ग सेमी","36 वर्ग सेमी","48 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: हीरोन सूत्र: s = (9 + 10 + 17)/2 = 18<br>चरण 2: s−a = 9, s−b = 8, s−c = 1<br>चरण 3: क्षेत्रफल = √(18 × 9 × 8 × 1) = √1296 = 36<br>अतः उत्तर = <b>36 वर्ग सेमी</b><br><b>ध्यान दें:</b> यह समकोण त्रिभुज नहीं है, इसलिए ½ × 9 × 10 = 45 (विकल्प A) गलत है।"},
    {"q":"एक समद्विबाहु त्रिभुज का परिमाप 50 सेमी और आधार 24 सेमी है। उसका क्षेत्रफल कितना है?","o":["120 वर्ग सेमी","78 वर्ग सेमी","65 वर्ग सेमी","60 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: बराबर भुजाएँ = (50 − 24)/2 = 13 सेमी<br>चरण 2: लंब आधार को 12 + 12 में बाँटता है ⇒ ऊँचाई = √(13² − 12²) = √25 = 5 सेमी<br>चरण 3: क्षेत्रफल = ½ × 24 × 5 = 60<br>अतः उत्तर = <b>60 वर्ग सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर 120 (विकल्प A) आता है।"},
    {"q":"यदि किसी वृत्त की परिधि 50% बढ़ा दी जाए, तो उसका क्षेत्रफल कितने प्रतिशत बढ़ेगा?","o":["125%","50%","100%","225%"],"a":0,"e":"<b>हल:</b><br>चरण 1: परिधि = 2πr, अतः परिधि 50% बढ़े तो त्रिज्या भी 50% बढ़ती है ⇒ नई त्रिज्या = 1.5r<br>चरण 2: नया क्षेत्रफल = π(1.5r)² = 2.25πr²<br>चरण 3: वृद्धि = 2.25 − 1 = 1.25 = 125%<br>अतः उत्तर = <b>125%</b><br><b>शॉर्टकट:</b> 50 + 50 + (50 × 50)/100 = 125%।<br><b>ध्यान दें:</b> 225% (विकल्प D) नया क्षेत्रफल है (मूल का 225%), वृद्धि नहीं।"},
    {"q":"एक वर्ग का विकर्ण 10 सेमी है। उसका क्षेत्रफल कितना है?","o":["100 वर्ग सेमी","50 वर्ग सेमी","25 वर्ग सेमी","20 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग का क्षेत्रफल = (विकर्ण)²/2<br>चरण 2: = 10²/2 = 100/2 = 50<br>अतः उत्तर = <b>50 वर्ग सेमी</b><br><b>ध्यान दें:</b> भुजा = 10/√2 = 5√2, (5√2)² = 50 — 100 (विकल्प A) विकर्ण को भुजा मानने से आता है।"},
    {"q":"21 मी त्रिज्या वाले एक वृत्ताकार बगीचे के बाहर चारों ओर 3.5 मी चौड़ा रास्ता बना है। रास्ते का क्षेत्रफल कितना है? (π = 22/7)","o":["462 वर्ग मी","539 वर्ग मी","500.5 वर्ग मी","481.25 वर्ग मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: भीतरी त्रिज्या r = 21 मी, बाहरी R = 21 + 3.5 = 24.5 मी<br>चरण 2: रास्ते का क्षेत्रफल = π(R + r)(R − r) = 22/7 × 45.5 × 3.5<br>चरण 3: 3.5/7 = 0.5 ⇒ = 22 × 45.5 × 0.5 = 22 × 22.75 = 500.5<br>अतः उत्तर = <b>500.5 वर्ग मी</b><br><b>ध्यान दें:</b> 462 (विकल्प A) केवल परिधि × चौड़ाई (132 × 3.5) है।"},
    {"q":"एक समचतुर्भुज का क्षेत्रफल 120 वर्ग सेमी और एक विकर्ण 10 सेमी है। उसकी भुजा कितनी है?","o":["12 सेमी","24 सेमी","15 सेमी","13 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल = ½ × d₁ × d₂ ⇒ 120 = ½ × 10 × d₂ ⇒ d₂ = 24 सेमी<br>चरण 2: आधे विकर्ण = 5 और 12<br>चरण 3: भुजा = √(5² + 12²) = √169 = 13<br>अतः उत्तर = <b>13 सेमी</b><br><b>ध्यान दें:</b> 24 (विकल्प B) दूसरा विकर्ण है, भुजा नहीं।"},
    {"q":"एक समबाहु त्रिभुज की ऊँचाई 9 सेमी है। उसका क्षेत्रफल कितना है?","o":["27√3 वर्ग सेमी","81√3 वर्ग सेमी","9√3 वर्ग सेमी","36√3 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: h = (√3/2)a ⇒ 9 = (√3/2)a ⇒ a = 18/√3 = 6√3 सेमी<br>चरण 2: क्षेत्रफल = ½ × a × h = ½ × 6√3 × 9 = 27√3<br>अतः उत्तर = <b>27√3 वर्ग सेमी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = h²/√3 = 81/√3 = 27√3।"},
    {"q":"एक वृत्त का क्षेत्रफल 6 सेमी और 8 सेमी त्रिज्या वाले दो वृत्तों के क्षेत्रफलों के योग के बराबर है। उस वृत्त की त्रिज्या कितनी है?","o":["14 सेमी","10 सेमी","12 सेमी","7 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: πR² = π(6²) + π(8²)<br>चरण 2: R² = 36 + 64 = 100<br>चरण 3: R = 10<br>अतः उत्तर = <b>10 सेमी</b><br><b>ध्यान दें:</b> त्रिज्याएँ सीधे जोड़कर 14 (विकल्प A) लेना गलत है — क्षेत्रफल जुड़ते हैं, त्रिज्याएँ नहीं।"},
    {"q":"एक आयत की एक भुजा 15 सेमी और विकर्ण 17 सेमी है। आयत का क्षेत्रफल कितना है?","o":["255 वर्ग सेमी","136 वर्ग सेमी","120 वर्ग सेमी","105 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: दूसरी भुजा = √(17² − 15²) = √(289 − 225) = √64 = 8 सेमी<br>चरण 2: क्षेत्रफल = 15 × 8 = 120<br>अतः उत्तर = <b>120 वर्ग सेमी</b><br><b>शॉर्टकट:</b> 8-15-17 पाइथागोरियन त्रिक।"},
    {"q":"3 हेक्टेयर कितने एयर (are) के बराबर है?","o":["30 एयर","3000 एयर","3 एयर","300 एयर"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 एयर = 100 वर्ग मी; 1 हेक्टेयर = 10000 वर्ग मी = 100 एयर<br>चरण 2: 3 हेक्टेयर = 3 × 100 = 300 एयर<br>अतः उत्तर = <b>300 एयर</b>"},
    {"q":"एक त्रिभुज की भुजाएँ 20 सेमी, 21 सेमी और 29 सेमी हैं। उसका क्षेत्रफल कितना है?","o":["420 वर्ग सेमी","210 वर्ग सेमी","290 वर्ग सेमी","305 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: जाँचें — 20² + 21² = 400 + 441 = 841 = 29², अतः समकोण त्रिभुज (कर्ण 29)।<br>चरण 2: क्षेत्रफल = ½ × 20 × 21 = 210<br>अतः उत्तर = <b>210 वर्ग सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर 420 (विकल्प A) आता है। 20-21-29 त्रिक याद रखें।"},
    {"q":"एक समबाहु त्रिभुज की अंतःत्रिज्या 2√3 सेमी है। उसका क्षेत्रफल कितना है?","o":["12√3 वर्ग सेमी","48√3 वर्ग सेमी","36√3 वर्ग सेमी","24√3 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज की अंतःत्रिज्या r = a/(2√3)<br>चरण 2: a = 2√3 × r = 2√3 × 2√3 = 12 सेमी<br>चरण 3: क्षेत्रफल = (√3/4) × 12² = 36√3<br>अतः उत्तर = <b>36√3 वर्ग सेमी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = 3√3 r² = 3√3 × 12 = 36√3।"},
    {"q":"एक आयत की लंबाई उसकी चौड़ाई से 3 मी अधिक है और उसका क्षेत्रफल 108 वर्ग मी है। आयत का परिमाप कितना है?","o":["42 मी","36 मी","108 मी","48 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: चौड़ाई = b, लंबाई = b + 3 ⇒ b(b + 3) = 108<br>चरण 2: b² + 3b − 108 = 0 ⇒ (b + 12)(b − 9) = 0 ⇒ b = 9 मी<br>चरण 3: लंबाई = 12 मी ⇒ परिमाप = 2(12 + 9) = 42<br>अतः उत्तर = <b>42 मी</b><br><b>शॉर्टकट:</b> 108 के गुणनखंड जिनका अंतर 3 हो: 12 × 9।"},
    {"q":"एक आयत की लंबाई 4 मी घटाने और चौड़ाई 3 मी बढ़ाने पर वह समान क्षेत्रफल वाला वर्ग बन जाता है। आयत का परिमाप कितना है?","o":["48 मी","56 मी","44 मी","50 मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना वर्ग की भुजा s ⇒ l = s + 4, b = s − 3<br>चरण 2: क्षेत्रफल समान: (s + 4)(s − 3) = s²<br>चरण 3: s² + s − 12 = s² ⇒ s = 12<br>चरण 4: l = 16 मी, b = 9 मी ⇒ परिमाप = 2(16 + 9) = 50<br>अतः उत्तर = <b>50 मी</b><br><b>जाँच:</b> 16 × 9 = 144 = 12² ✓<br><b>ध्यान दें:</b> 48 मी (विकल्प A) वर्ग का परिमाप है, आयत का नहीं।"},
    {"q":"एक समांतर चतुर्भुज की आसन्न भुजाएँ 10 सेमी और 6 सेमी हैं तथा उनके बीच का कोण 30° है। उसका क्षेत्रफल कितना है?","o":["60 वर्ग सेमी","15 वर्ग सेमी","30 वर्ग सेमी","30√3 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: समांतर चतुर्भुज का क्षेत्रफल = ab sin θ<br>चरण 2: = 10 × 6 × sin 30° = 60 × ½ = 30<br>अतः उत्तर = <b>30 वर्ग सेमी</b><br><b>वैकल्पिक:</b> 10 सेमी आधार पर ऊँचाई = 6 sin 30° = 3 सेमी ⇒ 10 × 3 = 30।<br><b>ध्यान दें:</b> 60 (विकल्प A) कोण की उपेक्षा करने पर; 30√3 (विकल्प D) sin की जगह cos लेने पर आता है।"},
    {"q":"एक समचतुर्भुज की भुजा 10 सेमी और उसका एक कोण 60° है। उसका क्षेत्रफल कितना है?","o":["50√3 वर्ग सेमी","100 वर्ग सेमी","25√3 वर्ग सेमी","100√3 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: 60° कोण वाला समचतुर्भुज छोटे विकर्ण से दो समबाहु त्रिभुजों (भुजा 10) में बँटता है।<br>चरण 2: एक त्रिभुज = (√3/4) × 100 = 25√3<br>चरण 3: समचतुर्भुज = 2 × 25√3 = 50√3<br>अतः उत्तर = <b>50√3 वर्ग सेमी</b><br><b>वैकल्पिक:</b> a² sin θ = 100 × √3/2 = 50√3।<br><b>ध्यान दें:</b> 25√3 (विकल्प C) केवल एक त्रिभुज का क्षेत्रफल है।"},
    {"q":"एक चतुर्भुजाकार खेत का एक विकर्ण 24 मी है तथा शेष दो शीर्षों से इस विकर्ण पर डाले गए लंब 8 मी और 5 मी हैं। खेत का क्षेत्रफल कितना है?","o":["312 वर्ग मी","120 वर्ग मी","78 वर्ग मी","156 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: विकर्ण चतुर्भुज को दो त्रिभुजों में बाँटता है, दोनों का आधार = विकर्ण = 24 मी<br>चरण 2: त्रिभुज 1 = ½ × 24 × 8 = 96; त्रिभुज 2 = ½ × 24 × 5 = 60<br>चरण 3: कुल = 96 + 60 = 156<br>अतः उत्तर = <b>156 वर्ग मी</b><br><b>शॉर्टकट:</b> ½ × d × (h₁ + h₂) = 12 × 13 = 156।<br><b>ध्यान दें:</b> ½ भूलने पर 312 (विकल्प A) आता है।"},
    {"q":"एक वृत्त की परिधि उसके व्यास से 30 सेमी अधिक है। वृत्त की त्रिज्या कितनी है? (π = 22/7)","o":["14 सेमी","7 सेमी","10.5 सेमी","5 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: परिधि − व्यास = 2πr − 2r = 2r(π − 1) = 30<br>चरण 2: π − 1 = 22/7 − 1 = 15/7 ⇒ 2r × 15/7 = 30<br>चरण 3: 2r = 14 ⇒ r = 7<br>अतः उत्तर = <b>7 सेमी</b><br><b>ध्यान दें:</b> 14 सेमी (विकल्प A) व्यास है, त्रिज्या नहीं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. समान परिमाप वाले सभी आयतों में वर्ग का क्षेत्रफल अधिकतम होता है।<br>2. समान परिमाप वाले वर्ग और वृत्त में वर्ग का क्षेत्रफल अधिक होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>कथन 1: परिमाप स्थिर ⇒ l + b स्थिर; गुणनफल lb तब अधिकतम जब l = b (वर्ग)। — <b>सही</b><br>कथन 2: परिमाप 88 लें: वृत्त = 616, वर्ग = 484; वृत्त का क्षेत्रफल अधिक (अनुपात 14 : 11)। — <b>गलत</b><br>अतः उत्तर = <b>केवल 1</b><br><b>ध्यान दें:</b> दिए गए परिमाप पर सभी समतल आकृतियों में वृत्त का क्षेत्रफल सबसे अधिक होता है।"},
    {"q":"किसी वर्ग के परिवृत्त और अंतःवृत्त के क्षेत्रफलों का अनुपात क्या है?","o":["√2 : 1","4 : 1","2 : 1","π : 2"],"a":2,"e":"<b>हल:</b><br>चरण 1: भुजा a वाले वर्ग का परिवृत्त विकर्ण पर बनता है ⇒ R = a√2/2 = a/√2<br>चरण 2: अंतःवृत्त भुजाओं को छूता है ⇒ r = a/2<br>चरण 3: क्षेत्रफल अनुपात = R² : r² = (a²/2) : (a²/4) = 2 : 1<br>अतः उत्तर = <b>2 : 1</b><br><b>ध्यान दें:</b> √2 : 1 (विकल्प A) त्रिज्याओं का अनुपात है, क्षेत्रफल का नहीं।"},
    {"q":"14√3 सेमी भुजा वाले समबाहु त्रिभुज के अंतःवृत्त का क्षेत्रफल कितना है? (π = 22/7)","o":["616 वर्ग सेमी","308 वर्ग सेमी","462 वर्ग सेमी","154 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज की अंतःत्रिज्या r = a/(2√3)<br>चरण 2: r = 14√3/(2√3) = 7 सेमी<br>चरण 3: अंतःवृत्त का क्षेत्रफल = 22/7 × 7² = 154<br>अतः उत्तर = <b>154 वर्ग सेमी</b><br><b>ध्यान दें:</b> परित्रिज्या R = a/√3 = 14 लेने पर 616 (विकल्प A) आता है — वह परिवृत्त है।"},
    {"q":"एक वृत्त की त्रिज्या 1 सेमी बढ़ाने पर उसका क्षेत्रफल 22 वर्ग सेमी बढ़ जाता है। मूल त्रिज्या कितनी है? (π = 22/7)","o":["3.5 सेमी","3 सेमी","7 सेमी","4 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल में वृद्धि = π(r + 1)² − πr² = π(2r + 1)<br>चरण 2: 22/7 × (2r + 1) = 22 ⇒ 2r + 1 = 7<br>चरण 3: r = 3<br>अतः उत्तर = <b>3 सेमी</b><br><b>जाँच:</b> π(16 − 9) = 7π = 22 ✓"},
    {"q":"21 सेमी त्रिज्या वाले वृत्त के एक त्रिज्यखंड के चाप की लंबाई 22 सेमी है। त्रिज्यखंड का क्षेत्रफल कितना है?","o":["462 वर्ग सेमी","231 वर्ग सेमी","220.5 वर्ग सेमी","693 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: त्रिज्यखंड का क्षेत्रफल = ½ × चाप की लंबाई × त्रिज्या (क्योंकि (θ/360)πr² = ½ × [(θ/360)2πr] × r)<br>चरण 2: = ½ × 22 × 21 = 231<br>अतः उत्तर = <b>231 वर्ग सेमी</b><br><b>ध्यान दें:</b> ½ भूलने पर 462 (विकल्प A) आता है। यहाँ π या कोण निकालने की ज़रूरत नहीं।"},
    {"q":"14 सेमी त्रिज्या वाले वृत्त की वह जीवा जो केन्द्र पर 90° का कोण बनाती है, उससे बने लघु वृत्तखंड का क्षेत्रफल कितना है? (π = 22/7)","o":["154 वर्ग सेमी","98 वर्ग सेमी","252 वर्ग सेमी","56 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: लघु वृत्तखंड = त्रिज्यखंड − त्रिभुज (केन्द्र व जीवा के सिरों से बना)<br>चरण 2: त्रिज्यखंड (90°) = ¼ × 22/7 × 14² = ¼ × 616 = 154 वर्ग सेमी<br>चरण 3: त्रिभुज समकोण है: ½ × 14 × 14 = 98 वर्ग सेमी<br>चरण 4: वृत्तखंड = 154 − 98 = 56<br>अतः उत्तर = <b>56 वर्ग सेमी</b><br><b>ध्यान दें:</b> 154 (विकल्प A) त्रिज्यखंड है और 98 (विकल्प B) केवल त्रिभुज।"},
    {"q":"अभिकथन (A): किसी वृत्त की त्रिज्या दोगुनी करने पर उसका क्षेत्रफल चार गुना हो जाता है।<br>कारण (R): वृत्त का क्षेत्रफल उसकी त्रिज्या के वर्ग के समानुपाती होता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>अभिकथन (A): क्षेत्रफल = πr²; r → 2r करने पर π(2r)² = 4πr², अर्थात् चार गुना। — <b>सही</b><br>कारण (R): πr² में π स्थिरांक है, अतः क्षेत्रफल ∝ r²। — <b>सही</b><br>A का परिणाम सीधे R से निकलता है (2² = 4), अतः R, A की सही व्याख्या है।<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b>"},
    {"q":"सूची-I (आकृति) को सूची-II (क्षेत्रफल का सूत्र) से सुमेलित कीजिए —<br>(A) समबाहु त्रिभुज (B) समचतुर्भुज (C) समलंब चतुर्भुज (D) त्रिज्यखंड<br>1. ½ × d1 × d2 2. (√3/4)a² 3. (θ/360°) × πr² 4. ½ × (a + b) × h","o":["A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"a":2,"e":"<b>हल:</b><br>(A) समबाहु त्रिभुज → (√3/4)a² → 2<br>(B) समचतुर्भुज → ½ × d1 × d2 (विकर्णों से) → 1<br>(C) समलंब चतुर्भुज → ½ × (a + b) × h → 4<br>(D) त्रिज्यखंड → (θ/360°) × πr² → 3<br>अतः उत्तर = <b>A-2, B-1, C-4, D-3</b><br><b>ध्यान दें:</b> A-2 और B-1 तय होते ही विकल्प B और C बचते हैं; समलंब का सूत्र ½(a + b)h (4) है, इसलिए C।"},
    {"q":"एक आयताकार खेत का क्षेत्रफल 1200 वर्ग मी है और उसकी लंबाई व चौड़ाई का अनुपात 4 : 3 है। ₹10 प्रति मीटर की दर से उसके चारों ओर बाड़ लगाने का खर्च कितना होगा?","o":["₹1400","₹700","₹1200","₹1600"],"a":0,"e":"<b>हल:</b><br>चरण 1: l = 4k, b = 3k ⇒ 12k² = 1200 ⇒ k² = 100 ⇒ k = 10<br>चरण 2: l = 40 मी, b = 30 मी<br>चरण 3: परिमाप = 2(40 + 30) = 140 मी<br>चरण 4: खर्च = 140 × 10 = ₹1400<br>अतः उत्तर = <b>₹1400</b><br><b>ध्यान दें:</b> l + b = 70 को ही परिमाप मानने पर ₹700 (विकल्प B) आता है।"},
    {"q":"28 मी भुजा वाले वर्गाकार मैदान के एक कोने पर 14 मी लंबी रस्सी से एक घोड़ा बँधा है। घोड़ा मैदान के कितने क्षेत्र में चर सकता है? (π = 22/7)","o":["616 वर्ग मी","308 वर्ग मी","196 वर्ग मी","154 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: वर्ग के कोने पर कोण 90° है, अतः घोड़ा 14 मी त्रिज्या के चतुर्थांश (¼ वृत्त) में चरेगा। (14 < 28, इसलिए रस्सी मैदान के भीतर रहती है)<br>चरण 2: क्षेत्रफल = ¼ × 22/7 × 14² = ¼ × 616 = 154<br>अतः उत्तर = <b>154 वर्ग मी</b><br><b>ध्यान दें:</b> 616 (विकल्प A) पूरा वृत्त है — मैदान के अंदर केवल ¼ भाग आता है।"},
    {"q":"एक गाय 7 मी लंबी रस्सी से एक खूँटे पर बँधी है। वह दोगुने क्षेत्र में चर सके, इसके लिए रस्सी कितनी लंबी होनी चाहिए?","o":["14 मी","10 मी","7√2 मी","49 मी"],"a":2,"e":"<b>हल:</b><br>चरण 1: चरने का क्षेत्र = πr² ⇒ क्षेत्रफल ∝ r²<br>चरण 2: नया क्षेत्र = 2 × π × 7² ⇒ πR² = 98π ⇒ R² = 98<br>चरण 3: R = √98 = 7√2 मी (≈ 9.9 मी)<br>अतः उत्तर = <b>7√2 मी</b><br><b>ध्यान दें:</b> रस्सी दोगुनी (14 मी) करने पर क्षेत्र चार गुना हो जाता है, दोगुना नहीं।"},
    {"q":"14 सेमी भुजा वाले वर्ग के चारों शीर्षों को केन्द्र मानकर 7 सेमी त्रिज्या के चार चतुर्थांश काट दिए गए। शेष भाग का क्षेत्रफल कितना है? (π = 22/7)","o":["154 वर्ग सेमी","42 वर्ग सेमी","56 वर्ग सेमी","38.5 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग के चारों कोनों पर 90° के चतुर्थांश ⇒ 4 × ¼ वृत्त = एक पूर्ण वृत्त (r = 7)<br>चरण 2: वृत्त का क्षेत्रफल = 22/7 × 49 = 154 वर्ग सेमी<br>चरण 3: वर्ग = 14² = 196 वर्ग सेमी<br>चरण 4: शेष = 196 − 154 = 42<br>अतः उत्तर = <b>42 वर्ग सेमी</b><br><b>ध्यान दें:</b> 154 (विकल्प A) काटा गया भाग है, शेष नहीं।"},
    {"q":"एक वर्ग का क्षेत्रफल 32 सेमी × 18 सेमी वाले आयत के क्षेत्रफल के बराबर है। वर्ग का परिमाप कितना है?","o":["100 सेमी","88 सेमी","24 सेमी","96 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: आयत का क्षेत्रफल = 32 × 18 = 576 वर्ग सेमी<br>चरण 2: वर्ग की भुजा = √576 = 24 सेमी<br>चरण 3: परिमाप = 4 × 24 = 96<br>अतः उत्तर = <b>96 सेमी</b><br><b>ध्यान दें:</b> 24 (विकल्प C) भुजा है; 100 सेमी आयत का परिमाप है।"},
    {"q":"एक समद्विबाहु समकोण त्रिभुज का कर्ण 10√2 सेमी है। उसका क्षेत्रफल कितना है?","o":["50 वर्ग सेमी","100 वर्ग सेमी","25 वर्ग सेमी","50√2 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समद्विबाहु समकोण त्रिभुज में कर्ण = a√2<br>चरण 2: a = 10√2/√2 = 10 सेमी<br>चरण 3: क्षेत्रफल = ½ × 10 × 10 = 50<br>अतः उत्तर = <b>50 वर्ग सेमी</b><br><b>शॉर्टकट:</b> क्षेत्रफल = कर्ण²/4 = 200/4 = 50।"},
    {"q":"4 सेमी भुजा वाले सम षट्भुज का क्षेत्रफल कितना है?","o":["16√3 वर्ग सेमी","12√3 वर्ग सेमी","24√3 वर्ग सेमी","48√3 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: सम षट्भुज केन्द्र से 6 समबाहु त्रिभुजों में बँटता है, प्रत्येक की भुजा = 4 सेमी<br>चरण 2: एक त्रिभुज = (√3/4) × 4² = 4√3<br>चरण 3: षट्भुज = 6 × 4√3 = 24√3<br>अतः उत्तर = <b>24√3 वर्ग सेमी</b><br><b>सूत्र:</b> सम षट्भुज = (3√3/2)a²।"},
    {"q":"एक समचतुर्भुज के विकर्णों का अनुपात 3 : 4 है और उसका परिमाप 40 सेमी है। उसका क्षेत्रफल कितना है?","o":["48 वर्ग सेमी","96 वर्ग सेमी","100 वर्ग सेमी","192 वर्ग सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: भुजा = 40/4 = 10 सेमी<br>चरण 2: विकर्ण 3 : 4 ⇒ आधे विकर्ण 3k और 4k; पाइथागोरस: 5k = 10 ⇒ k = 2<br>चरण 3: आधे विकर्ण = 6, 8 ⇒ विकर्ण = 12 और 16 सेमी<br>चरण 4: क्षेत्रफल = ½ × 12 × 16 = 96<br>अतः उत्तर = <b>96 वर्ग सेमी</b><br><b>ध्यान दें:</b> 100 (विकल्प C) भुजा² है — वह केवल वर्ग के लिए सही होता।"},
    {"q":"समान परिमाप वाले एक समबाहु त्रिभुज और एक वर्ग के क्षेत्रफलों का अनुपात क्या है?","o":["3 : 4","9 : 4√3","4√3 : 9","√3 : 4"],"a":2,"e":"<b>हल:</b><br>चरण 1: सुविधा के लिए परिमाप = 12 लें (3 और 4 दोनों से विभाज्य)<br>चरण 2: त्रिभुज की भुजा = 4 ⇒ क्षेत्रफल = (√3/4) × 16 = 4√3<br>चरण 3: वर्ग की भुजा = 3 ⇒ क्षेत्रफल = 9<br>चरण 4: अनुपात = 4√3 : 9<br>अतः उत्तर = <b>4√3 : 9</b><br><b>ध्यान दें:</b> 4√3 ≈ 6.93 < 9 — समान परिमाप पर त्रिभुज का क्षेत्रफल वर्ग से कम; 9 : 4√3 (विकल्प B) उल्टा क्रम है।"},
    {"q":"1 हेक्टेयर के घास के मैदान की कटाई का खर्च ₹2 प्रति 10 वर्ग मी की दर से कितना होगा?","o":["₹200","₹20000","₹1000","₹2000"],"a":3,"e":"<b>हल:</b><br>चरण 1: 1 हेक्टेयर = 10000 वर्ग मी<br>चरण 2: 10 वर्ग मी की इकाइयाँ = 10000 ÷ 10 = 1000<br>चरण 3: खर्च = 1000 × ₹2 = ₹2000<br>अतः उत्तर = <b>₹2000</b><br><b>ध्यान दें:</b> दर \"प्रति 10 वर्ग मी\" है; 10000 × 2 = ₹20000 (विकल्प B) प्रति वर्ग मी मानने की गलती है।"},
    {"q":"एक त्रिभुज और एक समांतर चतुर्भुज एक ही आधार पर तथा एक ही समांतर रेखाओं के बीच स्थित हैं। उनके क्षेत्रफलों का अनुपात (त्रिभुज : समांतर चतुर्भुज) क्या है?","o":["1 : 1","1 : 2","2 : 1","1 : 4"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही समांतर रेखाओं के बीच ⇒ दोनों की ऊँचाई h समान; आधार b भी समान<br>चरण 2: त्रिभुज = ½bh, समांतर चतुर्भुज = bh<br>चरण 3: अनुपात = ½ : 1 = 1 : 2<br>अतः उत्तर = <b>1 : 2</b>"},
    {"q":"किसी त्रिभुज की माध्यिका उसे दो ऐसे त्रिभुजों में बाँटती है जिनके —","o":["क्षेत्रफल बराबर होते हैं","परिमाप बराबर होते हैं","सभी कोण बराबर होते हैं","क्षेत्रफल 1 : 2 के अनुपात में होते हैं"],"a":0,"e":"<b>हल:</b><br>चरण 1: माध्यिका शीर्ष को सम्मुख भुजा के मध्य-बिंदु से मिलाती है ⇒ आधार दो बराबर भागों में बँटता है।<br>चरण 2: दोनों छोटे त्रिभुजों की ऊँचाई वही (शीर्ष से आधार पर लंब) है।<br>चरण 3: बराबर आधार × समान ऊँचाई ⇒ क्षेत्रफल बराबर<br>अतः उत्तर = <b>क्षेत्रफल बराबर होते हैं</b><br><b>ध्यान दें:</b> परिमाप और कोण सामान्यतः बराबर नहीं होते (केवल समद्विबाहु/समबाहु में विशेष स्थिति)।"},
    {"q":"एक वर्गाकार खेत का विकर्ण 50 मी है। उसका क्षेत्रफल हेक्टेयर में कितना है?","o":["0.25 हेक्टेयर","0.125 हेक्टेयर","1.25 हेक्टेयर","0.0625 हेक्टेयर"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग का क्षेत्रफल = d²/2 = 50²/2 = 2500/2 = 1250 वर्ग मी<br>चरण 2: 1 हेक्टेयर = 10000 वर्ग मी<br>चरण 3: 1250 ÷ 10000 = 0.125 हेक्टेयर<br>अतः उत्तर = <b>0.125 हेक्टेयर</b><br><b>ध्यान दें:</b> d² = 2500 को क्षेत्रफल मानने पर 0.25 (विकल्प A) आता है।"},
    {"q":"40 मी × 30 मी के एक आयताकार भूखंड में 7 मी त्रिज्या का एक वृत्ताकार तालाब है। भूखंड का शेष क्षेत्रफल कितना है? (π = 22/7)","o":["1200 वर्ग मी","1144 वर्ग मी","1062 वर्ग मी","1046 वर्ग मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: भूखंड = 40 × 30 = 1200 वर्ग मी<br>चरण 2: तालाब = πr² = 22/7 × 49 = 154 वर्ग मी<br>चरण 3: शेष = 1200 − 154 = 1046<br>अतः उत्तर = <b>1046 वर्ग मी</b><br><b>ध्यान दें:</b> 1144 (विकल्प B) में तालाब की परिधि 44 घटा दी गई — घटाना क्षेत्रफल πr² है।"},
    {"q":"एक वर्ग का परिमाप, 21 सेमी त्रिज्या वाले वृत्त की परिधि के बराबर है। वर्ग का क्षेत्रफल कितना है? (π = 22/7)","o":["1386 वर्ग सेमी","4356 वर्ग सेमी","1089 वर्ग सेमी","1024 वर्ग सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: वृत्त की परिधि = 2 × 22/7 × 21 = 132 सेमी<br>चरण 2: वर्ग का परिमाप = 132 ⇒ भुजा = 132/4 = 33 सेमी<br>चरण 3: क्षेत्रफल = 33² = 1089<br>अतः उत्तर = <b>1089 वर्ग सेमी</b><br><b>ध्यान दें:</b> 1386 (विकल्प A) वृत्त का क्षेत्रफल है।"},
    {"q":"16√3 वर्ग सेमी क्षेत्रफल वाले समबाहु त्रिभुज के आकार के तार को मोड़कर एक वर्ग बनाया गया। वर्ग का क्षेत्रफल कितना है?","o":["36 वर्ग सेमी","64 वर्ग सेमी","48 वर्ग सेमी","16 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: (√3/4)a² = 16√3 ⇒ a² = 64 ⇒ a = 8 सेमी<br>चरण 2: तार की लंबाई = त्रिभुज का परिमाप = 3 × 8 = 24 सेमी<br>चरण 3: वर्ग की भुजा = 24/4 = 6 सेमी<br>चरण 4: वर्ग का क्षेत्रफल = 6² = 36<br>अतः उत्तर = <b>36 वर्ग सेमी</b><br><b>ध्यान दें:</b> 64 (विकल्प B) त्रिभुज की भुजा a² है, वर्ग नहीं।"},
    {"q":"एक त्रिभुज की दो भुजाएँ 8 सेमी और 10 सेमी हैं तथा उनके बीच का कोण 30° है। त्रिभुज का क्षेत्रफल कितना है?","o":["40 वर्ग सेमी","80 वर्ग सेमी","20√3 वर्ग सेमी","20 वर्ग सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: दो भुजाएँ व उनके बीच का कोण ज्ञात ⇒ क्षेत्रफल = ½ ab sin C<br>चरण 2: = ½ × 8 × 10 × sin 30° = ½ × 80 × ½<br>चरण 3: = 20<br>अतः उत्तर = <b>20 वर्ग सेमी</b><br><b>ध्यान दें:</b> sin 30° = ½, cos 30° = √3/2; cos लेने पर 20√3 (विकल्प C) आता है।"},
    {"q":"14 सेमी × 7 सेमी के आयत में 14 सेमी लंबी भुजा को व्यास मानकर एक अर्धवृत्त काटा गया। शेष भाग का क्षेत्रफल कितना है? (π = 22/7)","o":["21 वर्ग सेमी","56 वर्ग सेमी","42 वर्ग सेमी","77 वर्ग सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: आयत = 14 × 7 = 98 वर्ग सेमी<br>चरण 2: अर्धवृत्त का व्यास 14 ⇒ r = 7 (चौड़ाई 7 के बराबर, अतः अर्धवृत्त आयत में ठीक समाता है)<br>चरण 3: अर्धवृत्त = ½ × 22/7 × 49 = 77 वर्ग सेमी<br>चरण 4: शेष = 98 − 77 = 21<br>अतः उत्तर = <b>21 वर्ग सेमी</b><br><b>ध्यान दें:</b> 77 (विकल्प D) काटा गया भाग है।"},
    {"q":"एक वर्गाकार खेत का क्षेत्रफल 1.21 हेक्टेयर है। उसका परिमाप कितना है?","o":["110 मी","440 मी","484 मी","4400 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1.21 हेक्टेयर = 1.21 × 10000 = 12100 वर्ग मी<br>चरण 2: भुजा = √12100 = 110 मी<br>चरण 3: परिमाप = 4 × 110 = 440<br>अतः उत्तर = <b>440 मी</b><br><b>ध्यान दें:</b> 110 मी (विकल्प A) केवल भुजा है।"},
    {"q":"एक समबाहु त्रिभुज की प्रत्येक भुजा 2 सेमी बढ़ाने पर उसका क्षेत्रफल 6√3 वर्ग सेमी बढ़ जाता है। मूल भुजा कितनी है?","o":["4 सेमी","6 सेमी","5 सेमी","3 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: क्षेत्रफल में वृद्धि = (√3/4)[(a + 2)² − a²]<br>चरण 2: (a + 2)² − a² = 4a + 4 ⇒ वृद्धि = (√3/4)(4a + 4) = √3(a + 1)<br>चरण 3: √3(a + 1) = 6√3 ⇒ a + 1 = 6 ⇒ a = 5<br>अतः उत्तर = <b>5 सेमी</b><br><b>जाँच:</b> (√3/4)(49 − 25) = (√3/4) × 24 = 6√3 ✓"}
  ]
});
